  await expectThrow(
    "取不存在的 ID → NotFound",
    () => service.getConfigFormData("999999999"),
    "配置不存在"
  );
  await expectThrow("非法 ID → BadRequest", () => service.getConfigFormData("abc"), "格式不正确");

  console.log("\n=== 4) 修改与唯一键冲突 ===");
