 * 认证服务
 *
 * 负责用户登录认证、令牌签发与刷新、登出等核心功能
 */
@Injectable()
export class AuthService {
  constructor(
    @Inject(jwtConfig.KEY)
    private readonly config: ConfigType<typeof jwtConfig>,
    private readonly jwtService: JwtService,
    private readonly userService: UserService,
    private readonly redisCacheService: RedisService,
    private readonly configService: ConfigService,
    private readonly logService: LogService
  ) {}

  /**
   * 获取用户 JWT 会话缓存键
   */
  private getJwtUserSessionKey(userId: string): string {
    return `${RedisConstants.Auth.USER_JWT_SESSION}:${userId}`;
  }

  /**
   * 签发令牌
   *
   * 根据会话类型配置采用不同的令牌策略：
   * - jwt: JWT 自包含模式，用户信息存储在 Token 中
   * - redis-token: Redis 索引模式，Token 仅作为索引，用户会话存储在 Redis
   */
  private async issueTokens(user: any): Promise<LoginResultDto> {
    const sessionType = this.configService.get<string>("SESSION_TYPE") || "jwt";

    // JWT 模式：令牌自包含用户信息
    if (sessionType === "jwt") {
      const userId = user.id;

      // Token 版本控制，用于批量失效历史 Token
      const versionKey = `${RedisConstants.Auth.USER_TOKEN_VERSION}:${userId}`;
      const currentVersionRaw = await this.redisCacheService.get<number>(versionKey);
      const tokenVersion = currentVersionRaw ?? 0;

      // 缓存用户会话（不包含 perms，权限从角色权限缓存动态获取）
      const refreshTtl = this.config.expiresIn * 10;
      await this.redisCacheService.set(
        this.getJwtUserSessionKey(userId),
        {
          userId,
          username: user.username,
          deptId: user.deptId,
          dataScopes: user.dataScopes,
          deptTreePath: user.deptTreePath,
          roles: user.roles,
        },
        refreshTtl
      );

      // 构建 JWT payload
      const jti = uuidv4();
      const payload = {
        sub: userId,
        username: user.username,
        deptId: user.deptId,
        dataScopes: user.dataScopes,
        deptTreePath: user.deptTreePath,
        roles: user.roles,
        // 租户归属（PEL-11）：只进令牌，不接受请求参数。
        // sys_user 尚无 tenant_id 列（租户模型归 P0-03-01），平台账号暂为 null；
        // 待 P0-03-01 出租户模型后从 user 行回填。
        tenantId: (user as { tenantId?: string | null }).tenantId ?? null,
        tokenVersion,
        jti,
      };

      const accessToken = await this.jwtService.signAsync(payload, {
        expiresIn: this.config.expiresIn,
      });

      const refreshToken = await this.jwtService.signAsync(
        {
          ...payload,
          refreshToken: true,
        },
        {
          expiresIn: this.config.expiresIn * 10,
        }
      );

      return {
        tokenType: "Bearer",
        accessToken,
        refreshToken,
        expiresIn: this.config.expiresIn,
      };
    }

    // Redis-Token 模式：Token 仅作为索引
    const userId = user.id;
    const accessToken = uuidv4();
    const refreshToken = uuidv4();

    const accessTtl = this.config.expiresIn;
    const refreshTtl = this.config.expiresIn * 10;

    // 用户会话（不包含 perms）
    const userSession = {
      userId: userId,
      username: user.username,
      deptId: user.deptId,
      dataScopes: user.dataScopes,
      roles: user.roles,
    };

    // 存储 access/refresh 双 Token 及 userId 反向索引
    await this.redisCacheService.set(`auth:token:access:${accessToken}`, userSession, accessTtl);
    await this.redisCacheService.set(`auth:token:refresh:${refreshToken}`, userSession, refreshTtl);
    await this.redisCacheService.set(`auth:user:access:${userId}`, accessToken, accessTtl);
    await this.redisCacheService.set(`auth:user:refresh:${userId}`, refreshToken, refreshTtl);

    return {
      tokenType: "Bearer",
      accessToken,
      refreshToken,
      expiresIn: accessTtl,
    };
  }

  /**
   * 验证用户凭证
   */
  async validateUser(username: string, password: string): Promise<any> {
    const user = await this.userService.getAuthCredentialsByUsername(username);
    if (!user) {
      return null;
    }
    if (await bcrypt.compare(password, user.password)) {
      const { password: _password, ...result } = user;
      return result;
    }
    return null;
  }

  /**
   * 用户登录认证
   */
  async login(loginDto: LoginRequestDto): Promise<LoginResultDto> {
    const { username, password } = loginDto;
    const user = await this.validateUser(username, password);
    if (!user) {
      throw new BusinessException(ErrorCode.USER_PASSWORD_ERROR);
    }
    if (user.status === 0) {
      throw new BusinessException(ErrorCode.ACCOUNT_FROZEN);
    }

    const result = await this.issueTokens(user);

    // 手动记录登录日志（Public 接口无法通过拦截器获取 userId）
    this.logService
      .saveManualLog({
        module: LogModuleValue.LOGIN,
        actionType: ActionTypeValue.LOGIN,
        operatorId: user.id,
        operatorName: user.username,
        requestMethod: "POST",
        requestUri: "/api/v1/auth/login",
        status: 1,
      })
      .catch(() => {});

    return result;
  }

  /**
   * 发送短信登录验证码
   */
  async sendSmsLoginCode(mobile: string) {
    if (!mobile) {
      throw new BusinessException(ErrorCode.REQUEST_REQUIRED_PARAMETER_IS_EMPTY);
    }
    const code = "1234";
    await this.redisCacheService.set(`captcha:sms_login:${mobile}`, code, 300);
  }

  /**
   * 短信验证码登录
   */
  async loginBySms(mobile: string, code: string) {
    if (!mobile || !code) {
      throw new BusinessException(ErrorCode.REQUEST_REQUIRED_PARAMETER_IS_EMPTY);
    }

    const cacheCode = await this.redisCacheService.get<string>(`captcha:sms_login:${mobile}`);
    if (!cacheCode) {
      throw new BusinessException(ErrorCode.USER_VERIFICATION_CODE_EXPIRED);
    }
    if (String(cacheCode).trim() !== String(code).trim()) {
      throw new BusinessException(ErrorCode.USER_VERIFICATION_CODE_ERROR);
    }

    const user = await this.userService.findByMobile(mobile);
    if (!user) {
      throw new BusinessException(ErrorCode.ACCOUNT_NOT_FOUND);
    }
    if (user.status === 0) {
      throw new BusinessException(ErrorCode.ACCOUNT_FROZEN);
    }
    const result = await this.issueTokens(user);

    // 手动记录登录日志（Public 接口无法通过拦截器获取 userId）
    this.logService
      .saveManualLog({
        module: LogModuleValue.LOGIN,
        actionType: ActionTypeValue.LOGIN,
        operatorId: user.id,
        operatorName: user.username,
        requestMethod: "POST",
        requestUri: "/api/v1/auth/login/sms",
        status: 1,
      })
      .catch(() => {});

    return result;
  }

  /**
   * 刷新访问令牌
   */
  async refreshToken(refreshToken: string) {
    if (!refreshToken) {
      throw new BusinessException(ErrorCode.REQUEST_REQUIRED_PARAMETER_IS_EMPTY);
    }

    const sessionType = this.configService.get<string>("SESSION_TYPE") || "jwt";

    // JWT 模式
    if (sessionType === "jwt") {
      try {
        const payload: any = await this.jwtService.verifyAsync(refreshToken, {
          secret: this.config.secretKey,
          ignoreExpiration: false,
        });

        if (!payload || payload.refreshToken !== true) {
          throw new BusinessException(ErrorCode.REFRESH_TOKEN_INVALID);
        }

        const userId = payload.sub;

        // 校验 Token 版本
        const tokenVersion: number = payload.tokenVersion ?? 0;
        const versionKey = `${RedisConstants.Auth.USER_TOKEN_VERSION}:${userId}`;
        const currentVersionRaw = await this.redisCacheService.get<number>(versionKey);
        const currentVersion = currentVersionRaw ?? 0;
        if (tokenVersion < currentVersion) {
          throw new BusinessException(ErrorCode.REFRESH_TOKEN_INVALID);
        }

        // 校验黑名单
        const jti: string | undefined = payload.jti;
        if (jti) {
          const blacklistKey = `${RedisConstants.Auth.TOKEN_BLACKLIST}:${jti}`;
          const inBlacklist = await this.redisCacheService.hasKey(blacklistKey);
          if (inBlacklist) {
            throw new BusinessException(ErrorCode.REFRESH_TOKEN_INVALID);
          }
        }

        // 签发新的访问令牌
        const newJti = uuidv4();
        const newAccessToken = await this.jwtService.signAsync(
          {
            sub: payload.sub,
            username: payload.username,
            deptId: payload.deptId,
            dataScopes: payload.dataScopes,
            deptTreePath: payload.deptTreePath,
            roles: payload.roles,
            // 刷新时透传租户归属（PEL-11）
            tenantId: payload.tenantId ?? null,
            tokenVersion: tokenVersion,
            jti: newJti,
          },
          {
            expiresIn: this.config.expiresIn,
          }
        );

        return {
          tokenType: "Bearer",
          accessToken: newAccessToken,
          refreshToken,
          expiresIn: this.config.expiresIn,
        };
      } catch {
        throw new BusinessException(ErrorCode.REFRESH_TOKEN_INVALID);
      }
    }

    // Redis-Token 模式
    const userSession = await this.redisCacheService.get<any>(`auth:token:refresh:${refreshToken}`);
    if (!userSession) {
      throw new BusinessException(ErrorCode.REFRESH_TOKEN_INVALID);
    }

    const accessToken = uuidv4();
    const accessTtl = this.config.expiresIn;

    await this.redisCacheService.set(`auth:token:access:${accessToken}`, userSession, accessTtl);
    await this.redisCacheService.set(
      `auth:user:access:${userSession.userId}`,
      accessToken,
      accessTtl
    );

    return {
      tokenType: "Bearer",
      accessToken,
      refreshToken,
      expiresIn: accessTtl,
    };
  }

  /**
   * 注销登录
   */
  async logout() {
    // 实际黑名单逻辑由 AuthController 传入原始 Bearer Token 后调用本方法完成
    return;
  }

  /**
   * 将 JWT 令牌加入黑名单
   *
   * @param token Bearer Token 或裸 Token
   */
  async blacklistToken(token: string): Promise<void> {
    if (!token) {
      return;
    }

    // 剥离 Bearer 前缀
    if (token.startsWith("Bearer ")) {
      token = token.substring("Bearer ".length);
    }

    const decoded: any = this.jwtService.decode(token);
    if (!decoded) {
      return;
    }

    const jti: string | undefined = decoded["jti"];
    const exp: number | undefined = decoded["exp"];

    if (!jti || !exp) {
      return;
    }

    const nowSeconds = Math.floor(Date.now() / 1000);
    const remaining = exp - nowSeconds;
    if (remaining <= 0) {
      return;
    }

    const blacklistKey = `${RedisConstants.Auth.TOKEN_BLACKLIST}:${jti}`;
    await this.redisCacheService.set(blacklistKey, true, remaining);
  }
}

import { CanActivate, ExecutionContext, Injectable } from "@nestjs/common";
import { RedisService } from "../../common/redis/redis.service";
import { BusinessException } from "../../common/exceptions/business.exception";
import { ErrorCode } from "../../common/enums/error-code.enum";

/**
 * Redis 会话模式下的认证守卫
 *
 * - 从 Authorization: Bearer <accessToken> 中获取访问令牌
 * - 使用 Redis 映射 auth:token:access:{accessToken} -> UserSession
 * - 未命中则视为未登录
 */
@Injectable()
export class RedisTokenAuthGuard implements CanActivate {
  constructor(private readonly redisCacheService: RedisService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const authHeader: string | undefined = request.headers["authorization"];

    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      throw new BusinessException(ErrorCode.ACCESS_TOKEN_INVALID);
    }

    const accessToken = authHeader.substring("Bearer ".length);
    const userSession = await this.redisCacheService.get<any>(`auth:token:access:${accessToken}`);

    if (!userSession) {
      throw new BusinessException(ErrorCode.ACCESS_TOKEN_INVALID);
    }

    // 挂载到 request.user，供后续控制器 / 守卫使用
    request.user = userSession;
    return true;
  }
}

import { Injectable, UnauthorizedException } from "@nestjs/common";
import { PassportStrategy } from "@nestjs/passport";
import { ExtractJwt, Strategy } from "passport-jwt";
import { ConfigService } from "@nestjs/config";
import { RedisService } from "../../common/redis/redis.service";
import { RoleService } from "../../system/role/role.service";
import { RedisConstants } from "../../common/constants/redis.constants";

/**
 * JWT 认证策略
 *
 * 解析并验证 JWT 令牌，将令牌载荷转换为标准化的用户对象
 * 处理令牌过期、签名有效性等底层验证
 *
 * 注意：权限标识（perms）不在此处获取，而是在权限守卫中从角色权限缓存动态读取
 */
@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(
    private readonly configService: ConfigService,
    private readonly redisCacheService: RedisService,
    private readonly roleService: RoleService
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.getOrThrow<string>("jwt.secretKey"),
    });
  }

  /**
   * 验证并标准化 JWT 载荷
   *
   * @param payload 解码后的 JWT 载荷
   * @returns 标准用户对象 (将挂载到 req.user)
   */
  async validate(payload: any) {
    if (!payload.sub || !payload.username) {
      throw new UnauthorizedException("无效的令牌载荷");
    }

    const userId = payload.sub;

    // 校验 Token 版本号
    const tokenVersion: number = payload.tokenVersion ?? 0;
    const versionKey = `${RedisConstants.Auth.USER_TOKEN_VERSION}:${userId}`;
    const currentVersionRaw = await this.redisCacheService.get<number>(versionKey);
    const currentVersion = currentVersionRaw ?? 0;

    if (tokenVersion < currentVersion) {
      throw new UnauthorizedException("Token 已失效，请重新登录");
    }

    // 校验黑名单
    const jti: string | undefined = payload.jti;
    if (jti) {
      const blacklistKey = `${RedisConstants.Auth.TOKEN_BLACKLIST}:${jti}`;
      const inBlacklist = await this.redisCacheService.hasKey(blacklistKey);
      if (inBlacklist) {
        throw new UnauthorizedException("Token 已失效，请重新登录");
      }
    }

    const roles: string[] = payload.roles || [];

    // 获取角色的数据权限列表
    const dataScopes = await this.roleService.getRoleDataScopes(roles);

    return {
      userId,
      username: payload.username,
      roles,
      deptId: payload.deptId,
      dataScopes,
      deptTreePath: payload.deptTreePath,
      // 租户归属只信令牌，不接受请求参数传入（PEL-11）；平台账号当前为 null
      tenantId: payload.tenantId ?? null,
    };
  }
}

import { Injectable } from "@nestjs/common";
import { Prisma } from "@prisma/client";
const JSZip = require("jszip");
import * as fs from "fs";
import * as path from "path";
// velocityjs 没有稳定的 TS 类型定义，使用 any
import * as Velocity from "velocityjs";

import { PrismaService } from "../common/prisma/prisma.service";
import { toBigInt } from "../common/prisma/prisma-ids";
import { formatDateTimeInZone } from "../common/utils/date.util";

import type { CodegenPreviewDto } from "./dto/codegen-preview.dto";
import type { GenConfigFormDto, FieldConfigDto } from "./dto/gen-config-form.dto";
import type { TableQueryDto } from "./dto/table-query.dto";

type TemplateName =
  | "API"
  | "API_TYPES"
  | "VIEW"
  | "Controller"
  | "Service"
  | "Module"
  | "PrismaModel"
  | "DtoQuery"
  | "DtoForm"
  | "DtoCreate"
  | "DtoUpdate";

interface TemplateConfig {
  templatePath: string;
  subpackageName: string;
  extension: string;
}

/**
 * 代码生成服务（PEL-10：TypeORM/MySQL → Prisma/PostgreSQL）
 *
 * ─────────────────────────────────────────────────────────────
 * 🔴 本次迁移改了什么
 *  ① **内省数据源**：`DataSource.query()`（MySQL 方言）→ `PrismaService.$queryRaw()` +
 *     PostgreSQL 系统目录。原 SQL 里以下写法在 PG 上**直接报错或不成立**：
 *     · `DATABASE()` → `current_schema()`
 *     · `b'0'` / `b'1'` → `0` / `1`（PG 的 `bit` 与 `smallint` 不可直接比较，会抛类型错误）
 *     · `LIMIT ? OFFSET ?` → `LIMIT $n OFFSET $m`（走 `Prisma.sql` 参数化，不是字符串拼接）
 *     · `DATE_FORMAT(...)` → 不适用（见 ②）
 *  ② **面向 PG 的字段能力差异（已按「保留键、置空值」处理，不再假装等价）**：
 *     · `tableComment` → `obj_description(oid,'pg_class')`，**PG 有等价物** ✅
 *     · `engine`（存储引擎）→ PG 无此概念 ⇒ `null`
 *     · `tableCollation`（表级排序规则）→ PG 的排序规则是**列级**而非表级 ⇒ `null`
 *     · `createTime`（建表时间）→ **PG 的系统目录不记录建表时间** ⇒ `null`。
 *       连带：原 `ORDER BY CREATE_TIME DESC` 失去依据，改为 `ORDER BY table_name ASC`
 *       以保证**分页结果确定**（否则翻页会漏/重）。
 *  ③ **`gen_table` / `gen_table_column` 读写改走 Prisma 模型**（`GenTable` / `GenTableColumn`），
 *     不再手写 SQL。用**基础客户端**（`this.prisma.genTable`）而非 `scoped` —— 代码生成配置属
 *     系统元数据，不该被数据权限过滤（`data-scope.extension` 也只在声明了 `@DataPermission`
 *     的模型上注入，此处从未声明）。
 *  ④ **类型映射口径从 MySQL 改为 PostgreSQL**，但**中间类型词表刻意保持不变**
 *     （`String`/`Integer`/`Long`/`Float`/`Double`/`BigDecimal`/`LocalDate`/`LocalDateTime`/
 *     `Boolean`/`byte[]`）。原因有二：
 *     · `gen_table_column.field_type` 会把该值**落库**，换词表等于让已保存的配置语义漂移；
 *     · 前端 curd 模板（`frontend/{ts,js}/index.curd*.vue.vm`，共 6 处）按 `javaType` 做控件推断，
 *       键名与取值都必须照旧。⇒ **`javaType` 这个键名是历史遗留**，虽已无 Java 语义，
 *       改名会让 6 个前端模板同时退化，故保留。
 *  ⑤ **`entity.ts.vm` → `prisma-model.prisma.vm`**：不再产出 TypeORM 实体（本项目模型由
 *     `schema.prisma` 单一来源），改为产出**可直接粘贴进 `schema.prisma` 的 `model` 块**，
 *     并带上 `@map` / `@@map` / `@db.*` 原生类型与字段注释。输出路径随之变为
 *     `<backendAppName>/prisma/models/<table-kebab>.prisma`。
 *  ⑥ **`module.ts.vm` / `service.ts.vm` 改成 Prisma 形态**：去掉 `TypeOrmModule.forFeature`、
 *     `@InjectRepository`、`Repository`、`createQueryBuilder`，改为注入 `PrismaService`
 *     并构造 `Prisma.XxxWhereInput`。
 *
 * ─────────────────────────────────────────────────────────────
 * ⚠️ 刻意保持的原有行为（不顺手统一）
 *  ① `packageName` **恒取默认值** `src`，忽略 DTO 与库中已有的 `package_name`
 *     ⇒ 前端把该字段改掉后，保存再读取会被抹回默认值。原实现即如此（保存时写的是
 *     默认值、读取时也返回默认值，两处都忽略入参），保留。
 *  ② `deleteGenConfig` 的查配置 SELECT **不带 `is_deleted` 过滤** ⇒ 对已逻辑删除的配置
 *     再删一次仍会命中并再次置 `is_deleted = 1`（幂等，无副作用）。
 *  ③ `saveGenConfig` 更新分支会把 `is_deleted` 置 `0` ⇒ **保存即「复活」**曾被删除的配置，
 *     原实现即如此（原 SQL 里写死 `is_deleted = b'0'`）。
 *
 * ─────────────────────────────────────────────────────────────
 * ✅ 顺带修掉的两处（都会导致 400/500，属确定性缺陷）
 *  ① `getGenConfig` 对未配置表的 `moduleName` 回退：原实现直接返回库里的 `module_name`，
 *     而该列**可空** ⇒ 返回 `null` 后 `getPreview()` 用它拼路径会得到字面量 `"null"`。
 *     现回退到默认模块名（与 `saveGenConfig` 的 `body.moduleName || 默认值` 口径一致）。
 *  ② `saveGenConfig` 写字段配置时 `field_name` 直接用 DTO 的值，但该列 **NOT NULL**
 *     ⇒ DTO 不带 `fieldName` 时会写入 `null` 并抛原始 Prisma 错误。现回退为
 *     「由 `columnName` 推导的驼峰名」，保证一定满足非空约束。
 */
@Injectable()
export class CodegenService {
  constructor(private readonly prisma: PrismaService) {}

  private readonly codegenConfig = {
    downloadFileName: "niulai-admin-code.zip",
    backendAppName: "niulai-nest",
    frontendAppName: "vue3-element-admin",
    defaultAuthor: "niulaitech",
    defaultModuleName: "system",
    defaultPackageName: "src",
    defaultRemoveTablePrefix: "sys_",
  };

  private readonly templateConfigs: Record<TemplateName, TemplateConfig> = {
    API: { templatePath: "frontend/ts/api.ts.vm", subpackageName: "api", extension: ".ts" },
    API_TYPES: {
      templatePath: "frontend/ts/api-types.ts.vm",
      subpackageName: "types",
      extension: ".ts",
    },
    VIEW: { templatePath: "frontend/ts/index.vue.vm", subpackageName: "views", extension: ".vue" },
    Controller: {
      templatePath: "backend/controller.ts.vm",
      subpackageName: "",
      extension: ".ts",
    },
    Service: {
      templatePath: "backend/service.ts.vm",
      subpackageName: "",
      extension: ".ts",
    },
    Module: {
      templatePath: "backend/module.ts.vm",
      subpackageName: "",
      extension: ".ts",
    },
    /** 取代原 `Entity`（TypeORM 实体）—— 产出 Prisma `model` 块 */
    PrismaModel: {
      templatePath: "backend/prisma-model.prisma.vm",
      subpackageName: "models",
      extension: ".prisma",
    },
    DtoQuery: {
      templatePath: "backend/dto-query.ts.vm",
      subpackageName: "dto",
      extension: ".ts",
    },
    DtoForm: {
      templatePath: "backend/dto-form.ts.vm",
      subpackageName: "dto",
      extension: ".ts",
    },
    DtoCreate: {
      templatePath: "backend/dto-create.ts.vm",
      subpackageName: "dto",
      extension: ".ts",
    },
    DtoUpdate: {
      templatePath: "backend/dto-update.ts.vm",
      subpackageName: "dto",
      extension: ".ts",
    },
  };

  /**
   * 解析前端模板路径
   * @param templateName 模板标识
   * @param templateConfig 模板配置
   * @param frontendType 前端类型
   */
  private resolveFrontendTemplatePath(
    templateName: TemplateName,
    templateConfig: TemplateConfig,
    frontendType: string
  ) {
    if (frontendType !== "js") {
      return templateConfig.templatePath;
    }
    if (templateName === "API") {
      return "frontend/js/api.js.vm";
    }
    if (templateName === "VIEW") {
      return "frontend/js/index.js.vue.vm";
    }
    return templateConfig.templatePath;
  }

  /**
   * 解析前端文件后缀
   * @param templateName 模板标识
   * @param templateConfig 模板配置
   * @param frontendType 前端类型
   */
  private resolveFrontendExtension(
    templateName: TemplateName,
    templateConfig: TemplateConfig,
    frontendType: string
  ) {
    if (frontendType !== "js") {
      return templateConfig.extension;
    }
    if (templateName === "API") {
      return ".js";
    }
    return templateConfig.extension;
  }

  /**
   * 解析文件范围
   */
  private resolveScope(templateName: TemplateName) {
    if (templateName === "API" || templateName === "API_TYPES" || templateName === "VIEW") {
      return "frontend" as const;
    }
    return "backend" as const;
  }

  /**
   * 解析文件语言（扩展名）
   */
  private resolveLanguage(fileName: string) {
    const ext = path.extname(fileName);
    return ext.startsWith(".") ? ext.slice(1).toLowerCase() : "";
  }

  /**
   * 数据表分页列表（PostgreSQL 系统目录内省）
   */
  async getTablePage(query: TableQueryDto) {
    const { pageNum, pageSize, keywords } = query;

    const pageNumSafe = Number(pageNum) > 0 ? Number(pageNum) : 1;
    const pageSizeSafe = Number(pageSize) > 0 ? Number(pageSize) : 20;
    const offset = (pageNumSafe - 1) * pageSizeSafe;

    const conditions: Prisma.Sql[] = [
      Prisma.sql`t.table_schema = current_schema()`,
      // 只列基表（PG 的 information_schema 也会把视图/外部表列出来）
      Prisma.sql`t.table_type = 'BASE TABLE'`,
      // 排除代码生成元数据表；`_prisma_migrations` 是 Prisma 自身的迁移记录表
      // （迁移到 PG 后才出现的「基础设施表」，与 gen_* 同理，不该成为代码生成的候选）
      Prisma.sql`t.table_name NOT IN ('gen_table', 'gen_table_column', '_prisma_migrations')`,
    ];
    if (keywords) {
      // 旧库 MySQL 的 LIKE 默认不区分大小写；PG 的 LIKE 区分 ⇒ 用 ILIKE 对齐（清单约定 15）
      conditions.push(Prisma.sql`t.table_name ILIKE ${"%" + keywords + "%"}`);
    }
    const whereSql = Prisma.join(conditions, " AND ");

    const listSql = Prisma.sql`
      SELECT
        t.table_name AS "tableName",
        COALESCE(obj_description(pc.oid, 'pg_class'), '') AS "tableComment",
        NULL::text AS "tableCollation",
        NULL::text AS "engine",
        NULL::timestamptz AS "createTime",
        CASE WHEN g.id IS NULL THEN 0 ELSE 1 END AS "isConfigured"
      FROM information_schema.tables t
      JOIN pg_namespace pn ON pn.nspname = t.table_schema
      JOIN pg_class pc ON pc.relname = t.table_name AND pc.relnamespace = pn.oid
      LEFT JOIN gen_table g
        ON g.table_name = t.table_name AND g.is_deleted = 0
      WHERE ${whereSql}
      ORDER BY t.table_name ASC
      LIMIT ${pageSizeSafe} OFFSET ${offset}
    `;

    // `COUNT(1)` 在 PG 返回 bigint（Prisma 会给 JS BigInt）⇒ 显式 ::int 免去二次转换
    const totalSql = Prisma.sql`
      SELECT COUNT(1)::int AS total
      FROM information_schema.tables t
      WHERE ${whereSql}
    `;

    const [list, totalRows] = await Promise.all([
      this.prisma.$queryRaw<TableMetaRow[]>(listSql),
      this.prisma.$queryRaw<Array<{ total: number }>>(totalSql),
    ]);

    const total = Number(totalRows?.[0]?.total || 0);
    return {
      data: list,
      page: {
        pageNum: pageNumSafe,
        pageSize: pageSizeSafe,
        total,
      },
    };
  }

  async getGenConfig(tableName: string): Promise<GenConfigFormDto> {
    const config = await this.prisma.genTable.findFirst({
      where: { tableName, isDeleted: 0 },
    });

    if (config) {
      const fieldRows = await this.prisma.genTableColumn.findMany({
        where: { tableId: config.id },
        orderBy: { fieldSort: "asc" },
      });

      return {
        id: config.id.toString(),
        tableName: config.tableName,
        // ✅ 修复①：该列可空，原实现直接返回 null 会让 getPreview 拼出字面量 "null"
        moduleName: config.moduleName ?? this.codegenConfig.defaultModuleName,
        // ⚠️ 保持原行为①：恒取默认值，忽略库中 package_name
        packageName: this.codegenConfig.defaultPackageName,
        businessName: config.businessName,
        entityName: config.entityName,
        author: config.author,
        parentMenuId: config.parentMenuId ? config.parentMenuId.toString() : undefined,
        backendAppName: this.codegenConfig.backendAppName,
        frontendAppName: this.codegenConfig.frontendAppName,
        removeTablePrefix: this.codegenConfig.defaultRemoveTablePrefix,
        pageType: "classic",
        fieldConfigs: fieldRows.map((row) => this.toFieldConfig(row)),
      };
    }

    // 未配置时按表结构生成配置
    const tableComment = await this.getTableComment(tableName);
    const businessName = tableComment ? tableComment.replace("表", "").trim() : tableName;

    const removePrefix = this.codegenConfig.defaultRemoveTablePrefix;
    const processed =
      removePrefix && tableName.startsWith(removePrefix)
        ? tableName.slice(removePrefix.length)
        : tableName;
    const entityName = toPascalCase(processed);

    const columns = await this.getTableColumns(tableName);

    const fieldConfigs: FieldConfigDto[] = (columns || []).map((col, idx) => {
      const columnType = String(col.columnType || "");
      return {
        columnName: col.columnName,
        columnType,
        fieldName: toCamelCase(String(col.columnName)),
        fieldType: getFieldTypeByColumnType(columnType),
        fieldComment: col.columnComment,
        isRequired: String(col.isNullable).toUpperCase() === "YES" ? 0 : 1,
        formType: getDefaultFormTypeByColumnType(columnType),
        queryType: 1, // EQ
        maxLength: col.maxLength ? Number(col.maxLength) : undefined,
        fieldSort: idx + 1,
        isShowInList: 1,
        isShowInForm: 1,
        isShowInQuery: 0,
      };
    });

    return {
      tableName,
      businessName,
      moduleName: this.codegenConfig.defaultModuleName,
      packageName: this.codegenConfig.defaultPackageName,
      entityName,
      author: this.codegenConfig.defaultAuthor,
      backendAppName: this.codegenConfig.backendAppName,
      frontendAppName: this.codegenConfig.frontendAppName,
      removeTablePrefix: removePrefix,
      pageType: "classic",
      fieldConfigs,
    };
  }

  async saveGenConfig(tableName: string, body: GenConfigFormDto) {
    const now = new Date();

    // 注意：此处**不过滤** is_deleted —— 原实现即如此，已被逻辑删除的配置会被「复活」
    const existing = await this.prisma.genTable.findFirst({
      where: { tableName },
      select: { id: true },
    });

    const moduleName = body.moduleName || this.codegenConfig.defaultModuleName;
    const packageName = this.codegenConfig.defaultPackageName;
    const businessName = body.businessName || tableName;
    const entityName = body.entityName || toPascalCase(tableName);
    const author = body.author || this.codegenConfig.defaultAuthor;
    const parentMenuId = body.parentMenuId ? toBigInt(body.parentMenuId) : null;

    let configId: bigint;
    if (existing) {
      configId = existing.id;
      await this.prisma.genTable.update({
        where: { id: configId },
        data: {
          moduleName,
          packageName,
          businessName,
          entityName,
          author,
          parentMenuId,
          updateTime: now,
          // ⚠️ 保持原行为③：保存即把 is_deleted 置 0（复活）
          isDeleted: 0,
        },
      });
    } else {
      const created = await this.prisma.genTable.create({
        data: {
          tableName,
          moduleName,
          packageName,
          businessName,
          entityName,
          author,
          parentMenuId,
          createTime: now,
          updateTime: now,
          isDeleted: 0,
        },
        select: { id: true },
      });
      configId = created.id;
    }

    // 先清理旧字段配置，再写入新配置
    await this.prisma.genTableColumn.deleteMany({ where: { tableId: configId } });

    const fieldConfigs = body.fieldConfigs || [];
    if (fieldConfigs.length) {
      await this.prisma.genTableColumn.createMany({
        data: fieldConfigs.map((f, i) => {
          const columnType = String(f.columnType || "");
          return {
            tableId: configId,
            columnName: f.columnName || null,
            columnType: columnType || null,
            // ✅ 修复②：field_name 是 NOT NULL，DTO 缺省时不能写 null
            fieldName: f.fieldName || toCamelCase(String(f.columnName || "")) || `field${i + 1}`,
            fieldType: f.fieldType || getFieldTypeByColumnType(columnType),
            fieldSort: f.fieldSort ?? i + 1,
            fieldComment: f.fieldComment || null,
            maxLength: f.maxLength ?? null,
            isRequired: f.isRequired ?? 0,
            isShowInList: f.isShowInList ?? 0,
            isShowInForm: f.isShowInForm ?? 0,
            isShowInQuery: f.isShowInQuery ?? 0,
            queryType: f.queryType ?? 1,
            formType: f.formType ?? getDefaultFormTypeByColumnType(columnType),
            dictType: f.dictType ?? null,
            createTime: now,
            updateTime: now,
          };
        }),
      });
    }

    return true;
  }

  async deleteGenConfig(tableName: string) {
    // ⚠️ 保持原行为②：此处不带 is_deleted 过滤
    const config = await this.prisma.genTable.findFirst({
      where: { tableName },
      select: { id: true },
    });
    if (!config) {
      return true;
    }

    await this.prisma.genTableColumn.deleteMany({ where: { tableId: config.id } });
    await this.prisma.genTable.update({
      where: { id: config.id },
      data: { isDeleted: 1, updateTime: new Date() },
    });

    return true;
  }

  /**
   * 获取预览代码
   * @param tableName 表名
   * @param pageType 页面类型
   * @param type 前端类型
   */
  async getPreview(
    tableName: string,
    pageType: "classic" | "curd" = "classic",
    type: "ts" | "js" = "ts"
  ): Promise<CodegenPreviewDto[]> {
    const config = await this.getGenConfig(tableName);
    const fieldConfigs = config.fieldConfigs || [];
    const frontendType = type === "js" ? "js" : "ts";

    const previews: CodegenPreviewDto[] = [];
    for (const [templateName, templateConfig] of Object.entries(this.templateConfigs) as [
      TemplateName,
      TemplateConfig,
    ][]) {
      if (frontendType === "js" && templateName === "API_TYPES") {
        continue;
      }

      const effectiveTemplatePath = this.resolveFrontendTemplatePath(
        templateName,
        templateConfig,
        frontendType
      );
      const extension = this.resolveFrontendExtension(templateName, templateConfig, frontendType);
      const fileName = this.getFileName(
        config.entityName!,
        templateName,
        extension,
        config.tableName
      );
      const filePath = this.getFilePath(
        templateName,
        config.moduleName!,
        config.packageName!,
        templateConfig.subpackageName,
        config.entityName!
      );

      const content = this.renderTemplate(
        templateName,
        effectiveTemplatePath,
        templateConfig.subpackageName,
        config,
        fieldConfigs,
        pageType
      );
      previews.push({
        path: filePath,
        fileName,
        content,
        scope: this.resolveScope(templateName),
        language: this.resolveLanguage(fileName),
      });
    }

    return previews;
  }

  /**
   * 下载代码
   * @param tableNames 表名列表
   * @param pageType 页面类型
   * @param type 前端类型
   */
  async downloadZip(
    tableNames: string[],
    pageType: "classic" | "curd" = "classic",
    type: "ts" | "js" = "ts"
  ) {
    const zip = new JSZip();

    for (const tableName of tableNames) {
      const list = await this.getPreview(tableName, pageType, type);
      for (const item of list) {
        const zipPath = `${item.path}/${item.fileName}`.replace(/\\/g, "/");
        zip.file(zipPath, item.content);
      }
    }

    const buffer = await zip.generateAsync({ type: "nodebuffer" });
    return { fileName: this.codegenConfig.downloadFileName, buffer };
  }

  /**
   * 渲染模板
   * @param templateName 模板标识
   * @param templatePath 模板路径
   * @param subpackageName 子包名
   * @param config 生成配置
   * @param fieldConfigs 字段配置
   * @param pageType 页面类型
   */
  private renderTemplate(
    templateName: TemplateName,
    templatePath: string,
    subpackageName: string,
    config: GenConfigFormDto,
    fieldConfigs: FieldConfigDto[],
    pageType: "classic" | "curd"
  ) {
    let effectivePath = templatePath;
    if (templateName === "VIEW" && pageType === "curd") {
      if (effectivePath.endsWith("index.js.vue.vm")) {
        effectivePath = effectivePath.replace(
          "frontend/js/index.js.vue.vm",
          "frontend/js/index.curd.js.vue.vm"
        );
      } else if (effectivePath.endsWith("index.vue.vm")) {
        effectivePath = effectivePath.replace(
          "frontend/ts/index.vue.vm",
          "frontend/ts/index.curd.vue.vm"
        );
      }
    }

    const absTemplatePath = resolveBootTemplatePath(effectivePath);
    const tpl = fs.readFileSync(absTemplatePath, "utf8");

    const entityName = config.entityName || "";
    const bindMap: any = {
      packageName: config.packageName,
      moduleName: config.moduleName,
      subpackageName,
      // 按应用时区格式化（清单约定 9）：`new Date().getHours()` 依赖进程时区，UTC 机器会差 8 小时
      date: formatDateTimeInZone(new Date()),
      entityName,
      tableName: config.tableName,
      tableKebab: toKebabCase(config.tableName || entityName),
      author: config.author,
      entityLowerCamel: lowerFirst(entityName),
      entityKebab: toKebabCase(entityName),
      entityUpperSnake: toSnakeUpper(entityName),
      dollar: "$",
      businessName: config.businessName,
      entityComment: config.businessName,
      fieldConfigs: fieldConfigs.map((f) => this.toTemplateFieldConfig(f)),
    };

    return (Velocity as any).render(tpl, bindMap);
  }

  private toTemplateFieldConfig(field: FieldConfigDto) {
    const fieldType = field.fieldType || getFieldTypeByColumnType(field.columnType || "");
    const prisma = getPrismaTypeByColumnType(field.columnType || "", field.maxLength);
    return {
      ...field,
      // ⚠️ `javaType` 是**历史遗留键名**，前端 curd 模板（6 处）按它做控件推断；
      //    取值词表刻意保持不变，改名/换词表会同时打坏那 6 个模板。
      javaType: fieldType,
      fieldType,
      tsType: getTsTypeByFieldType(fieldType),
      prismaType: prisma.type,
      prismaAttr: prisma.attr || "",
      // 🔴 `prisma-model.prisma.vm` 的字段行**不允许以指令收尾**。
      //    velocityjs 会吃掉「紧跟在指令标记之后」的换行 —— 无论该指令是独立占行还是行内，
      //    也无论后面跟不跟 `##`。后果是字段注释被粘到上一个字段行尾（模型语法直接坏掉），
      //    而**单字段 / 无注释的配置看不出来**，极易漏检。
      //    ⇒ 三个可选片段在这里预拼成纯文本，模板里只做插值，一个指令都不留。
      //    注：`prismaAttr` 本身保留（不带前导空格），供断言与二次拼接使用。
      prismaComment: field.fieldComment || "",
      prismaOptional: field.isRequired === 1 ? "" : "?",
      prismaAttrPart: prisma.attr ? ` ${prisma.attr}` : "",
      prismaMapPart:
        field.columnName && field.columnName !== field.fieldName
          ? ` @map("${field.columnName}")`
          : "",
      // Velocity 模板在比较时使用字符串枚举名
      formType: getFormTypeName(field.formType),
      queryType: getQueryTypeName(field.queryType),
    };
  }

  /** `gen_table_column` 行 → 对外字段配置（Prisma 返回 camelCase，仅需补默认值） */
  private toFieldConfig(row: GenTableColumnRow): FieldConfigDto {
    const columnType = row.columnType || "";
    return {
      id: row.id?.toString(),
      columnName: row.columnName ?? undefined,
      columnType,
      fieldName: row.fieldName,
      fieldType: row.fieldType || getFieldTypeByColumnType(columnType),
      fieldComment: row.fieldComment ?? undefined,
      isShowInList: row.isShowInList ?? 0,
      isShowInForm: row.isShowInForm ?? 0,
      isShowInQuery: row.isShowInQuery ?? 0,
      isRequired: row.isRequired ?? 0,
      formType: row.formType ?? getDefaultFormTypeByColumnType(columnType),
      queryType: row.queryType ?? 1,
      maxLength: row.maxLength ?? undefined,
      fieldSort: row.fieldSort ?? undefined,
      dictType: row.dictType ?? undefined,
    };
  }

  /** 取表注释（PG 的注释不在 information_schema 里，走 obj_description） */
  private async getTableComment(tableName: string): Promise<string> {
    const rows = await this.prisma.$queryRaw<Array<{ tableComment: string }>>`
      SELECT COALESCE(obj_description(pc.oid, 'pg_class'), '') AS "tableComment"
      FROM information_schema.tables t
      JOIN pg_namespace pn ON pn.nspname = t.table_schema
      JOIN pg_class pc ON pc.relname = t.table_name AND pc.relnamespace = pn.oid
      WHERE t.table_schema = current_schema() AND t.table_name = ${tableName}
      LIMIT 1
    `;
    return String(rows?.[0]?.tableComment || "");
  }

  /** 取列元数据（PG）。列注释同样走 pg_description 的 objsubid = 列序号 */
  private async getTableColumns(tableName: string): Promise<ColumnMetaRow[]> {
    return await this.prisma.$queryRaw<ColumnMetaRow[]>`
      SELECT
        c.column_name AS "columnName",
        c.data_type AS "columnType",
        COALESCE(pgd.description, '') AS "columnComment",
        c.is_nullable AS "isNullable",
        c.character_maximum_length AS "maxLength",
        c.ordinal_position AS "ordinalPosition"
      FROM information_schema.columns c
      JOIN pg_namespace pn ON pn.nspname = c.table_schema
      JOIN pg_class pc ON pc.relname = c.table_name AND pc.relnamespace = pn.oid
      LEFT JOIN pg_description pgd
        ON pgd.objoid = pc.oid AND pgd.objsubid = c.ordinal_position
      WHERE c.table_schema = current_schema() AND c.table_name = ${tableName}
      ORDER BY c.ordinal_position ASC
    `;
  }

  private getFileName(
    entityName: string,
    templateName: TemplateName,
    extension: string,
    tableName?: string
  ) {
    const entityKebab = toKebabCase(entityName);
    if (templateName === "PrismaModel") {
      const tableKebab = toKebabCase(tableName || entityName);
      return `${tableKebab}${extension}`;
    }
    if (templateName === "API") {
      return `index${extension}`;
    }
    if (templateName === "API_TYPES") {
      return `types${extension}`;
    }
    if (templateName === "VIEW") {
      return "index.vue";
    }
    if (templateName === "Controller") {
      return `${entityKebab}.controller${extension}`;
    }
    if (templateName === "Service") {
      return `${entityKebab}.service${extension}`;
    }
    if (templateName === "Module") {
      return `${entityKebab}.module${extension}`;
    }
    if (templateName === "DtoQuery") {
      return `${entityKebab}-query.dto${extension}`;
    }
    if (templateName === "DtoForm") {
      return `${entityKebab}-form.dto${extension}`;
    }
    if (templateName === "DtoCreate") {
      return `create-${entityKebab}.dto${extension}`;
    }
    if (templateName === "DtoUpdate") {
      return `update-${entityKebab}.dto${extension}`;
    }
    return `${entityName}${templateName}${extension}`;
  }

  private getFilePath(
    templateName: TemplateName,
    moduleName: string,
    packageName: string,
    subpackageName: string,
    entityName: string
  ) {
    const backend = this.codegenConfig.backendAppName;
    const frontend = this.codegenConfig.frontendAppName;

    if (templateName === "API" || templateName === "API_TYPES") {
      return path.join(frontend, "src", "api", moduleName, toKebabCase(entityName));
    }
    if (templateName === "VIEW") {
      return path.join(frontend, "src", subpackageName, moduleName, toKebabCase(entityName));
    }
    // Prisma 模型不是「某个业务模块下的文件」，而是 schema 的组成部分 ⇒ 落独立目录
    if (templateName === "PrismaModel") {
      return path.join(backend, "prisma", "models");
    }

    const featureDir = path.join(backend, "src", moduleName, toKebabCase(entityName));
    if (
      templateName === "DtoQuery" ||
      templateName === "DtoForm" ||
      templateName === "DtoCreate" ||
      templateName === "DtoUpdate"
    ) {
      return path.join(featureDir, "dto");
    }
    return featureDir;
  }
}

/** `information_schema.tables` 内省行（对外的表列表形状） */
export interface TableMetaRow {
  tableName: string;
  tableComment: string;
  /** PG 排序规则是列级而非表级 ⇒ 恒为 null（仅为对齐原接口形状而保留键） */
  tableCollation: string | null;
  /** PG 无存储引擎概念 ⇒ 恒为 null（仅为对齐原接口形状而保留键） */
  engine: string | null;
  /** PG 系统目录不记录建表时间 ⇒ 恒为 null；排序改按 table_name ASC 保证分页确定 */
  createTime: string | null;
  isConfigured: number;
}

/** `information_schema.columns` 内省行 */
export interface ColumnMetaRow {
  columnName: string;
  columnType: string;
  columnComment: string | null;
  isNullable: string;
  maxLength: number | null;
  ordinalPosition: number;
}

/** `gen_table_column` 的 Prisma 行形状（仅取本服务用到的列） */
export interface GenTableColumnRow {
  id: bigint;
  columnName: string | null;
  columnType: string | null;
  fieldName: string;
  fieldType: string | null;
  fieldSort: number | null;
  fieldComment: string | null;
  maxLength: number | null;
  isRequired: number | null;
  isShowInList: number | null;
  isShowInForm: number | null;
  isShowInQuery: number | null;
  queryType: number | null;
  formType: number | null;
  dictType: string | null;
}

function resolveBootTemplatePath(templatePath: string) {
  // 使用本地模板目录，模板路径：<project-root>/src/codegen/templates/<templatePath>
  const p = path.resolve(process.cwd(), "src", "codegen", "templates", templatePath);

  if (fs.existsSync(p)) {
    return p;
  }

  throw new Error(
    `Codegen template not found: '${templatePath}'. Expected location:\n  - ${p}\n\n` +
      `Please place templates under 'src/codegen/templates'.`
  );
}

function lowerFirst(s: string) {
  if (!s) return s;
  return s.charAt(0).toLowerCase() + s.slice(1);
}

function toCamelCase(s: string) {
  return String(s)
    .toLowerCase()
    .replace(/[_-](\w)/g, (_, c) => String(c).toUpperCase());
}

function toPascalCase(s: string) {
  const c = toCamelCase(s);
  return c ? c.charAt(0).toUpperCase() + c.slice(1) : c;
}

function toKebabCase(s: string) {
  return String(s)
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/_/g, "-")
    .toLowerCase();
}

function toSnakeUpper(s: string) {
  return String(s)
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/-/g, "_")
    .toUpperCase();
}

function normalizeColumnType(columnType: string) {
  return String(columnType || "")
    .trim()
    .toLowerCase()
    .replace(/unsigned/g, "")
    .replace(/zerofill/g, "")
    .replace(/\(.*\)/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * PostgreSQL `data_type` → 中间类型。
 *
 * ⚠️ 中间类型词表**刻意沿用**原 MySQL 版本（`String`/`Integer`/`Long`/… ），
 * 因为它会落库到 `gen_table_column.field_type`，且前端 curd 模板按 `javaType` 做控件推断。
 */
function getFieldTypeByColumnType(columnType: string) {
  const t = normalizeColumnType(columnType);
  switch (t) {
    case "character varying":
    case "character":
    case "text":
    case "json":
    case "jsonb":
    case "uuid":
    case "name":
    case "citext":
    case "inet":
    case "cidr":
    case "macaddr":
      return "String";
    case "bytea":
      return "byte[]";
    case "integer":
    case "smallint":
    case "serial":
    case "smallserial":
      return "Integer";
    case "bigint":
    case "bigserial":
    case "oid":
      return "Long";
    case "real":
      return "Float";
    case "double precision":
      return "Double";
    case "numeric":
    case "decimal":
    case "money":
      return "BigDecimal";
    case "date":
      return "LocalDate";
    case "timestamp with time zone":
    case "timestamp without time zone":
    case "time with time zone":
    case "time without time zone":
    case "interval":
      return "LocalDateTime";
    case "boolean":
    case "bit":
    case "bit varying":
      return "Boolean";
    default:
      return "String";
  }
}

/** 中间类型 → TypeScript 类型（供模板使用） */
function getTsTypeByFieldType(fieldType: string) {
  switch (fieldType) {
    case "String":
      return "string";
    case "Integer":
    case "Long":
    case "Float":
    case "Double":
    case "BigDecimal":
      return "number";
    case "Boolean":
      return "boolean";
    case "byte[]":
      return "Uint8Array";
    case "LocalDate":
    case "LocalDateTime":
      return "string";
    default:
      return "any";
  }
}

/**
 * PostgreSQL `data_type` → Prisma 标量类型 + 原生类型注解（供 `prisma-model.prisma.vm` 使用）。
 */
function getPrismaTypeByColumnType(
  columnType: string,
  maxLength?: number | null
): { type: string; attr?: string } {
  const t = normalizeColumnType(columnType);
  switch (t) {
    case "character varying":
      return { type: "String", attr: maxLength ? `@db.VarChar(${maxLength})` : undefined };
    case "character":
      return { type: "String", attr: maxLength ? `@db.Char(${maxLength})` : undefined };
    case "text":
      return { type: "String" };
    case "uuid":
      return { type: "String", attr: "@db.Uuid" };
    case "json":
      return { type: "Json", attr: "@db.Json" };
    case "jsonb":
      return { type: "Json", attr: "@db.JsonB" };
    case "bytea":
      return { type: "Bytes" };
    case "integer":
      return { type: "Int" };
    case "smallint":
      return { type: "Int", attr: "@db.SmallInt" };
    case "bigint":
      return { type: "BigInt" };
    case "real":
      return { type: "Float", attr: "@db.Real" };
    case "double precision":
      return { type: "Float" };
    case "numeric":
      return { type: "Decimal" };
    case "date":
      return { type: "DateTime", attr: "@db.Date" };
    case "timestamp with time zone":
      return { type: "DateTime", attr: "@db.Timestamptz(3)" };
    case "timestamp without time zone":
      return { type: "DateTime", attr: "@db.Timestamp(3)" };
    case "time without time zone":
      return { type: "DateTime", attr: "@db.Time" };
    case "boolean":
      return { type: "Boolean" };
    default:
      return { type: "String" };
  }
}

function getDefaultFormTypeByColumnType(columnType: string) {
  const t = normalizeColumnType(columnType);
  if (t === "date") return 8;
  if (t.startsWith("timestamp") || t.startsWith("time ")) return 9;
  return 1;
}

function getFormTypeName(value?: number) {
  switch (value) {
    case 1:
      return "INPUT";
    case 2:
      return "SELECT";
    case 3:
      return "RADIO";
    case 4:
      return "CHECK_BOX";
    case 5:
      return "INPUT_NUMBER";
    case 6:
      return "SWITCH";
    case 7:
      return "TEXT_AREA";
    case 8:
      return "DATE";
    case 9:
      return "DATE_TIME";
    case 10:
      return "HIDDEN";
    default:
      return "INPUT";
  }
}

function getQueryTypeName(value?: number) {
  switch (value) {
    case 1:
      return "EQ";
    case 2:
      return "LIKE";
    case 3:
      return "IN";
    case 4:
      return "BETWEEN";
    case 5:
      return "GT";
    case 6:
      return "GE";
    case 7:
      return "LT";
    case 8:
      return "LE";
    case 9:
      return "NE";
    case 10:
      return "LIKE_LEFT";
    case 11:
      return "LIKE_RIGHT";
    default:
      return "EQ";
  }
}

﻿import { SetMetadata } from "@nestjs/common";

export const DATA_PERMISSION_KEY = "data_permission";

/** 数据权限装饰器配置 */
export interface DataPermissionConfig {
  // ─────────── Prisma 形态（PEL-10c 起，新代码用这组） ───────────
  /** 施加数据权限的 Prisma 模型名（如 "SysUser"）。不声明则本请求不注入 */
  model?: string;
  /** 部门维度字段（Prisma 字段名，如 "deptId"） */
  deptField?: string;
  /** 归属人维度字段（Prisma 字段名，如 "createBy"） */
  ownerField?: string;

  // ─────────── TypeORM 遗留形态（迁移完成后删除） ───────────
  /** @deprecated 仅 TypeORM QueryBuilder 插件使用 */
  deptAlias?: string;
  /** @deprecated 仅 TypeORM QueryBuilder 插件使用 */
  deptIdColumnName?: string;
  /** @deprecated 仅 TypeORM QueryBuilder 插件使用 */
  userAlias?: string;
  /** @deprecated 仅 TypeORM QueryBuilder 插件使用 */
  userIdColumnName?: string;
}

/**
 * 数据权限装饰器
 *
 * 迁移期两套并存：Prisma 扩展读 `model/deptField/ownerField`，
 * TypeORM 插件读 `deptAlias/*ColumnName`。给同一个 handler 同时写两组即可，
 * TypeORM 摘除后把遗留字段一并删掉。
 */
export function DataPermission(config?: DataPermissionConfig): MethodDecorator & ClassDecorator {
  return (
    target: any,
    propertyKey?: string | symbol,
    descriptor?: TypedPropertyDescriptor<any>
  ) => {
    const finalConfig: DataPermissionConfig = {
      model: config?.model,
      deptField: config?.deptField,
      ownerField: config?.ownerField,
      deptAlias: config?.deptAlias,
      deptIdColumnName: config?.deptIdColumnName ?? "dept_id",
      userAlias: config?.userAlias,
      userIdColumnName: config?.userIdColumnName ?? "create_by",
    };

    if (descriptor) {
      SetMetadata(DATA_PERMISSION_KEY, finalConfig)(target, propertyKey, descriptor);
    } else {
      SetMetadata(DATA_PERMISSION_KEY, finalConfig)(target);
    }
  };
}

export const SKIP_DATA_PERMISSION_KEY = "skip_data_permission";

/** 跳过数据权限装饰器 */
export function SkipDataPermission(): MethodDecorator {
  return SetMetadata(SKIP_DATA_PERMISSION_KEY, true);
}

import { HttpStatus } from "@nestjs/common";

/**
 * 业务域错误码体系（CROSS-13）
 *
 * 与通用层 `error-code.enum.ts`（A/B/C，阿里风格）**并行**的一套业务域错误码：
 *  - **分段**：`1xxxx` 通用 / `2xxxx` 客户宠物 / `3xxxx` 预约订单 / `4xxxx` 支付 / `5xxxx` 寄养照护；
 *    每段预留 999 个码位（段内 `x001~x999`），段基线见 {@link DOMAIN_ERROR_SEGMENTS}。
 *  - **命名**：`域_对象_原因` 大写蛇形（如 `BOOKING_SLOT_CONFLICT`），作为响应信封 `code`
 *    的对外取值；数字 `code` 用于内部归组 / 监控告警。
 *  - **去重边界**：本文件只落「分段规则 + 注册守卫 + 各段代表条目」；各业务模块
 *    （P0-05 客户 / P0-06 宠物 / MVP 预约订单…）落地时在对应段位追加条目，
 *    追加必须走 {@link registerDomainError} 以获得分段与命名冲突检查。
 *
 * 错误信封：`{ code, msg, details? }` —— 字段名保留 `msg`（决策 A4）；
 * `details` 为可选的结构化错误明细（如字段级校验失败列表），由
 * `BusinessException` 第三参携带、`HttpExceptionFilter` 透传。
 */

export interface DomainErrorEntry {
  /** 数字分段错误码（如 30001），段位必须落在对应业务段区间内 */
  readonly code: number;
  /** `域_对象_原因`（大写蛇形），响应信封 `code` 的对外取值 */
  readonly name: string;
  /** 展示文案 */
  readonly msg: string;
  readonly httpStatus: HttpStatus;
}

/** 业务段基线：`[起始码, 结束码]`，闭区间 */
export const DOMAIN_ERROR_SEGMENTS = {
  /** 1xxxx 通用 */
  COMMON: [10000, 19999],
  /** 2xxxx 客户宠物 */
  CUSTOMER_PET: [20000, 29999],
  /** 3xxxx 预约订单 */
  BOOKING_ORDER: [30000, 39999],
  /** 4xxxx 支付 */
  PAYMENT: [40000, 49999],
  /** 5xxxx 寄养照护 */
  STAY_CARE: [50000, 59999],
} as const;

export type DomainErrorSegmentKey = keyof typeof DOMAIN_ERROR_SEGMENTS;

/** 已登记的业务域错误码（`域_对象_原因` → 条目），含启动期防冲突守卫所需全部信息 */
export const DOMAIN_ERROR_REGISTRY = new Map<string, DomainErrorEntry>();

function assertSegment(code: number, segment: readonly [number, number], key: string): void {
  if (code < segment[0] || code > segment[1]) {
    throw new Error(
      `[DomainErrorCode] 错误码 ${code} 不在 ${key} 段 [${segment[0]}, ${segment[1]}] 内`
    );
  }
}

/**
 * 登记一个业务域错误码（模块落地时追加条目的唯一入口）。
 * 冲突（数字码 / 命名重复）直接抛错，把问题拦在启动期而不是线上。
 */
export function registerDomainError(
  segmentKey: DomainErrorSegmentKey,
  entry: DomainErrorEntry
): DomainErrorEntry {
  const segment = DOMAIN_ERROR_SEGMENTS[segmentKey];
  assertSegment(entry.code, segment, segmentKey);
  if (DOMAIN_ERROR_REGISTRY.has(entry.name)) {
    throw new Error(`[DomainErrorCode] 命名冲突：${entry.name} 已登记`);
  }
  for (const existing of DOMAIN_ERROR_REGISTRY.values()) {
    if (existing.code === entry.code) {
      throw new Error(
        `[DomainErrorCode] 数字码冲突：${entry.code} 已被 ${existing.name} 占用`
      );
    }
  }
  DOMAIN_ERROR_REGISTRY.set(entry.name, entry);
  return entry;
}

/** 按 `域_对象_原因` 命名取错误条目；未登记返回 undefined（调用方决定兜底语义） */
export function getDomainError(name: string): DomainErrorEntry | undefined {
  return DOMAIN_ERROR_REGISTRY.get(name);
}

// ---------------------------------------------------------------------------
// 各段代表条目（验证分段机制的锚点；业务模块追加自己的条目时不允许与其冲突）
// ---------------------------------------------------------------------------

export const DomainErrorCode = {
  /** 2xxxx 客户宠物 · 代表条目 */
  CUSTOMER_NOT_FOUND: registerDomainError("CUSTOMER_PET", {
    code: 20001,
    name: "CUSTOMER_NOT_FOUND",
    msg: "客户不存在",
    httpStatus: HttpStatus.BAD_REQUEST,
  }),

  /** 3xxxx 预约订单 · 代表条目（任务说明中的示例） */
  BOOKING_SLOT_CONFLICT: registerDomainError("BOOKING_ORDER", {
    code: 30001,
    name: "BOOKING_SLOT_CONFLICT",
    msg: "预约时段冲突",
    httpStatus: HttpStatus.CONFLICT,
  }),

  /** 4xxxx 支付 · 代表条目 */
  PAYMENT_CHANNEL_ERROR: registerDomainError("PAYMENT", {
    code: 40001,
    name: "PAYMENT_CHANNEL_ERROR",
    msg: "支付渠道异常",
    httpStatus: HttpStatus.BAD_REQUEST,
  }),

  /** 5xxxx 寄养照护 · 代表条目 */
  STAY_ROOM_UNAVAILABLE: registerDomainError("STAY_CARE", {
    code: 50001,
    name: "STAY_ROOM_UNAVAILABLE",
    msg: "寄养房间不可用",
    httpStatus: HttpStatus.CONFLICT,
  }),
} as const;

﻿import { ExceptionFilter, Catch, ArgumentsHost, HttpStatus, HttpException } from "@nestjs/common";
import { Response } from "express";
import { BusinessException } from "../../common/exceptions/business.exception";
import { ErrorCode } from "../../common/enums/error-code.enum";

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();

    const isDuplicateEntryError = (ex: unknown): boolean => {
      if (!ex || typeof ex !== "object") return false;
      const anyEx = ex as any;
      const code = anyEx.code;
      const errno = anyEx.errno;
      const message = anyEx.message;
      // MySQL: ER_DUP_ENTRY / errno: 1062
      if (code === "ER_DUP_ENTRY" || errno === 1062) return true;
      if (typeof message === "string" && message.includes("Duplicate entry")) return true;
      return false;
    };

    const normalizeMsg = (value: unknown): string => {
      if (Array.isArray(value)) {
        const items = value
          .map((v) => (v === null || v === undefined ? "" : String(v)).trim())
          .filter((v) => v.length > 0);
        if (items.length > 0) return items.join("；");
        return ErrorCode.SYSTEM_ERROR.msg;
      }
      if (typeof value === "string") return value;
      if (value === null || value === undefined) return ErrorCode.SYSTEM_ERROR.msg;
      return String(value);
    };

    const buildResponseBody = (code: string, msg: string, details?: unknown) => {
      // 错误信封 `{ code, msg, details? }`（CROSS-13，决策 A4：字段名保留 msg）；
      // details 仅在调用方显式携带时出现，历史响应体形状不变。
      return details === undefined ? { code, msg, data: null } : { code, msg, details, data: null };
    };

    // 处理业务异常
    if (exception instanceof BusinessException) {
      const status = exception.getStatus();
      const exceptionResponse = exception.getResponse();

      const code = exceptionResponse["code"] || ErrorCode.SYSTEM_ERROR.code;
      const msg = exceptionResponse["msg"] || ErrorCode.SYSTEM_ERROR.msg;
      const details = exceptionResponse["details"];
      return response.status(status).json(buildResponseBody(code, msg, details));
    }

    // 处理NestJS内置HTTP异常
    if (exception instanceof HttpException) {
      const status = exception.getStatus();
      const exceptionResponse = exception.getResponse();

      // 认证错误返回 401，权限不足返回 403
      if (status === HttpStatus.UNAUTHORIZED) {
        return response
          .status(HttpStatus.UNAUTHORIZED)
          .json(
            buildResponseBody(
              ErrorCode.ACCESS_TOKEN_INVALID.code,
              ErrorCode.ACCESS_TOKEN_INVALID.msg
            )
          );
      }
      if (status === HttpStatus.FORBIDDEN) {
        return response
          .status(HttpStatus.FORBIDDEN)
          .json(
            buildResponseBody(
              ErrorCode.ACCESS_PERMISSION_EXCEPTION.code,
              ErrorCode.ACCESS_PERMISSION_EXCEPTION.msg
            )
          );
      }
      if (status === HttpStatus.NOT_FOUND) {
        return response
          .status(HttpStatus.NOT_FOUND)
          .json(
            buildResponseBody(ErrorCode.INTERFACE_NOT_EXIST.code, ErrorCode.INTERFACE_NOT_EXIST.msg)
          );
      }

      const msgRaw =
        typeof exceptionResponse === "object"
          ? ((exceptionResponse as any).message ?? ErrorCode.SYSTEM_ERROR.msg)
          : ((exceptionResponse as any) ?? ErrorCode.SYSTEM_ERROR.msg);
      const msg = normalizeMsg(msgRaw);

      if (status === HttpStatus.BAD_REQUEST || status === HttpStatus.UNPROCESSABLE_ENTITY) {
        return response
          .status(HttpStatus.OK)
          .json(buildResponseBody(ErrorCode.USER_REQUEST_PARAMETER_ERROR.code, msg));
      }

      return response
        .status(HttpStatus.INTERNAL_SERVER_ERROR)
        .json(buildResponseBody(ErrorCode.SYSTEM_ERROR.code, msg));
    }

    // 数据库唯一约束冲突等（TypeORM QueryFailedError 通常会落到这里）
    if (isDuplicateEntryError(exception)) {
      return response
        .status(HttpStatus.OK)
        .json(buildResponseBody(ErrorCode.INTEGRITY_CONSTRAINT_VIOLATION.code, "数据已存在"));
    }

    // 处理其他未捕获异常
    const status = HttpStatus.INTERNAL_SERVER_ERROR;
    const error = exception as Error;

    return response
      .status(status)
      .json(
        buildResponseBody(ErrorCode.SYSTEM_ERROR.code, error.message || ErrorCode.SYSTEM_ERROR.msg)
      );
  }
}

import { CanActivate, ExecutionContext, Injectable } from "@nestjs/common";
import { Reflector } from "@nestjs/core";
import { IS_PUBLIC_KEY } from "../../common/decorators/auth.decorator";
import { RequestContext } from "../context/request-context";
import { RoleDataScope } from "../../common/models/role-data-scope.model";

/**
 * 数据范围守卫
 * 从 request.user 提取用户信息和数据权限列表，写入 RequestContext
 */
@Injectable()
export class DataScopeGuard implements CanActivate {
  private readonly reflector: Reflector;

  constructor(reflector: Reflector) {
    this.reflector = reflector;
  }

  async canActivate(context: ExecutionContext): Promise<boolean> {
    // 公开接口不设置上下文
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) {
      RequestContext.setCurrentUser(null);
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const user = request.user || request["user"];

    // 未登录用户
    const userId = this.parseUserId(user?.userId);
    if (!userId) {
      RequestContext.setCurrentUser(null);
      return true;
    }

    // 解析用户上下文信息
    const deptId = this.parseId(user?.deptId);
    const deptTreePath = user?.deptTreePath ?? null;
    const roles = user?.roles ?? [];
    const perms = user?.perms ?? [];
    const isRoot = roles.includes("ROOT");

    // 多角色数据权限列表
    const dataScopes = this.parseDataScopes(user?.dataScopes);

    RequestContext.initUserContext({
      userId,
      deptId,
      deptTreePath,
      dataScopes,
      roles,
      perms,
      isRoot,
      // 租户归属随令牌一并写入上下文（PEL-11）；空值统一归一化为 null
      tenantId: user?.tenantId ? String(user.tenantId) : null,
    });

    return true;
  }

  /** 解析用户ID */
  private parseUserId(value: any): string | undefined {
    if (value === undefined || value === null || value === "") {
      return undefined;
    }
    return String(value);
  }

  /** 解析部门ID */
  private parseId(value: any): string | null {
    if (value === undefined || value === null || value === "") {
      return null;
    }
    return String(value);
  }

  /** 解析多角色数据权限 */
  private parseDataScopes(dataScopes: any): RoleDataScope[] {
    if (!dataScopes || !Array.isArray(dataScopes)) {
      return [];
    }
    return dataScopes.map((ds: any) => RoleDataScope.fromJSON(ds));
  }
}

import { ExecutionContext, Injectable } from "@nestjs/common";
import { Reflector } from "@nestjs/core";
import { AuthGuard as PassportAuthGuard } from "@nestjs/passport";
import { IS_PUBLIC_KEY } from "../../common/decorators/auth.decorator";
import { BusinessException } from "../../common/exceptions/business.exception";
import { ErrorCode } from "../../common/enums/error-code.enum";

/**
 * 认证守卫
 */
@Injectable()
export class JwtAuthGuard extends PassportAuthGuard("jwt") {
  constructor(private reflector: Reflector) {
    super();
  }

  /**
   * 路由访问控制逻辑
   */
  canActivate(context: ExecutionContext) {
    // 检查 @Public() 装饰器
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) return true;

    // 执行 Passport 验证流程
    return super.canActivate(context);
  }

  /**
   * 处理认证结果
   */
  handleRequest(err: any, user: any) {
    if (err || !user) {
      throw new BusinessException(ErrorCode.ACCESS_TOKEN_INVALID);
    }
    return user;
  }
}

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
} from "@nestjs/common";
import { Reflector } from "@nestjs/core";

import { ROOT_ROLE_CODE } from "../constants/role.constant";
import { METADATA } from "../constants/metadata.constant";
import { IS_PUBLIC_KEY } from "../../common/decorators/auth.decorator";
import { RolePermService } from "../../system/role/role-permission.service";

/**
 * RBAC 权限守卫
 *
 * 权限校验流程：
 * 1. Public 装饰器标记的接口直接放行
 * 2. 超级管理员（ROOT_ROLE_CODE）直接放行
 * 3. 未声明权限要求的接口放行
 * 4. 从角色权限缓存中获取用户权限，校验是否具备所需权限
 */
@Injectable()
export class PermissionGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    private readonly rolePermService: RolePermService
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    // Public 接口不做权限校验
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) {
      return true;
    }

    // 读取控制器/方法上声明的权限标识
    const requiredPerms = this.reflector.getAllAndOverride<string[]>(
      METADATA.PERMISSIONS,
      [context.getHandler(), context.getClass()]
    );

    // 未声明权限则视为不需要鉴权
    if (!requiredPerms?.length) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const user = request.user || request["user"];

    // 超级管理员放行
    const roles: string[] = Array.isArray(user?.roles) ? user.roles : [];
    if (roles.includes(ROOT_ROLE_CODE)) {
      return true;
    }

    // 从角色权限缓存获取用户权限
    const perms = await this.rolePermService.getPermsByRoleCodes(roles);

    // 校验是否具备任一所需权限
    const hasPerm = requiredPerms.some((perm) => perms.includes(perm));
    if (!hasPerm) {
      throw new ForbiddenException("权限不足");
    }

    return true;
  }
}

﻿import { Injectable, NestInterceptor, ExecutionContext, CallHandler } from "@nestjs/common";
import { Reflector } from "@nestjs/core";
import { Observable } from "rxjs";
import { finalize } from "rxjs/operators";
import { RequestContext, DataPermissionConfig } from "../context/request-context";
import {
  DATA_PERMISSION_KEY,
  SKIP_DATA_PERMISSION_KEY,
} from "../../common/decorators/data-permission.decorator";

/** 数据权限拦截器 */
@Injectable()
export class DataPermissionInterceptor implements NestInterceptor {
  constructor(private readonly reflector: Reflector) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const skipDataPermission = this.reflector.getAllAndOverride<boolean>(SKIP_DATA_PERMISSION_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (skipDataPermission) {
      RequestContext.setDataPermissionConfig(null);
      return next.handle();
    }

    const config = this.reflector.getAllAndOverride<DataPermissionConfig>(DATA_PERMISSION_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    RequestContext.setDataPermissionConfig(config || null);

    return next.handle().pipe(finalize(() => RequestContext.setDataPermissionConfig(null)));
  }
}

﻿import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  HttpStatus,
  Inject,
} from "@nestjs/common";
import { Observable } from "rxjs";
import { tap, map } from "rxjs/operators";
import { utils, XCommonRet } from "xmcommon";
import { Response, Request } from "express";
import { Reflector } from "@nestjs/core";
import { IS_PUBLIC_KEY } from "../decorators/auth.decorator";
import { WINSTON_MODULE_PROVIDER } from "nest-winston";
import { Logger } from "winston";
import { LoggerUtils } from "../../common/utils/logger.utils";

let requestSeq = 0;

@Injectable()
export class XRequestInterceptor implements NestInterceptor {
  @Inject(WINSTON_MODULE_PROVIDER)
  private logger: Logger;

  constructor(private reflector: Reflector) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const startTime = Date.now();
    const req = context.switchToHttp().getRequest<Request>();
    const res = context.switchToHttp().getResponse<Response>();
    const seq = requestSeq++;

    req["seq"] = seq;

    const isCheckAPI = !this.reflector.get<boolean>(IS_PUBLIC_KEY, context.getHandler());

    // 日志记录保持原始数据
    const logRequest = () => ({
      request: LoggerUtils.captureRequestContext(req),
      latency: Date.now() - startTime,
    });

    return next.handle().pipe(
      map((data) => {
        if (isCheckAPI) {
          this.logger.info("API Response", {
            ...logRequest(),
            response: data,
          });

          if (res.statusCode === HttpStatus.CREATED && req.method === "POST") {
            res.statusCode = HttpStatus.OK;
          }
        }

        return data instanceof XCommonRet ? this.formatXCommonRet(data) : data;
      }),
      tap(() => {
        this.logger.info(`Request ${seq} Completed`, {
          ...logRequest(),
          statusCode: res.statusCode,
        });
      })
    );
  }

  private formatXCommonRet(paramData: XCommonRet) {
    return {
      ret: paramData.err,
      msg: paramData.msg,
      data: utils.isNull(paramData.data) ? undefined : paramData.data,
    };
  }
}

import { of, lastValueFrom, Observable } from "rxjs";
import { CallHandler, ExecutionContext } from "@nestjs/common";
import { isPageResult } from "@peluvida/shared";
import { ResponseInterceptor } from "./response.interceptor";

/**
 * 响应拦截器单测 —— 覆盖 PEL-08「分页信封增量改造」
 *
 * 验收口径：
 * 1. 分页载荷返回 `list / total / page / page_size`；
 * 2. 外层保持 `code / msg / data` 不变；
 * 3. 存量前端读取 `data.list` / `data.total` 不回归；
 * 4. `page / page_size` 支持业务层 pageNum/pageSize、请求 query、默认值三级回落。
 */
describe("ResponseInterceptor（PEL-08 分页信封）", () => {
  function createInterceptor(skip = false): ResponseInterceptor<unknown> {
    const reflector = { getAllAndOverride: jest.fn().mockReturnValue(skip) } as any;
    return new ResponseInterceptor<unknown>(reflector);
  }

  function createContext(query: Record<string, unknown> = {}): ExecutionContext {
    return {
      getHandler: () => ({}),
      getClass: () => ({}),
      switchToHttp: () => ({ getRequest: () => ({ query }) }),
    } as any;
  }

  function callHandler(payload: unknown): CallHandler {
    return { handle: () => of(payload) } as CallHandler;
  }

  async function run(
    interceptor: ResponseInterceptor<unknown>,
    ctx: ExecutionContext,
    payload: unknown
  ): Promise<any> {
    return lastValueFrom(interceptor.intercept(ctx, callHandler(payload)) as Observable<any>);
  }

  it("分页载荷：输出 list / total / page / page_size", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: [{ id: 1 }, { id: 2 }],
      page: { pageNum: 2, pageSize: 20, total: 42 },
    });

    expect(res.code).toBe("00000");
    expect(res.msg).toBe("成功");
    expect(res.data.list).toEqual([{ id: 1 }, { id: 2 }]);
    expect(res.data.total).toBe(42);
    expect(res.data.page).toBe(2);
    expect(res.data.page_size).toBe(20);
  });

  it("外层结构保持 code / msg / data（存量前端零回归）", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: [],
      page: { pageNum: 1, pageSize: 10, total: 0 },
    });

    expect(Object.keys(res).sort()).toEqual(["code", "data", "msg"]);
    expect(res.data).toHaveProperty("list");
    expect(res.data).toHaveProperty("total");
  });

  it("page_size 超过上限 100 时截断", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: [],
      page: { pageNum: 1, pageSize: 999, total: 0 },
    });

    expect(res.data.page_size).toBe(100);
  });

  it("业务层未返回页码时回落到请求 query", async () => {
    const res = await run(createInterceptor(), createContext({ page: "3", page_size: "5" }), {
      data: [],
      page: { total: 8 },
    });

    expect(res.data.page).toBe(3);
    expect(res.data.page_size).toBe(5);
    expect(res.data.total).toBe(8);
  });

  it("业务层与 query 均缺失时使用默认值 1 / 20", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: [],
      page: { total: 3 },
    });

    expect(res.data.page).toBe(1);
    expect(res.data.page_size).toBe(20);
  });

  it("兼容 page.page / page.page_size 命名", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: [],
      page: { page: 4, page_size: 15, total: 60 },
    });

    expect(res.data.page).toBe(4);
    expect(res.data.page_size).toBe(15);
  });

  it("total 非数字时归零；list 非数组时归空数组", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: null,
      page: { pageNum: 1, pageSize: 20, total: undefined },
    });

    expect(res.data.list).toEqual([]);
    expect(res.data.total).toBe(0);
  });

  it("输出字段与 @peluvida/shared 的 PageResult 契约一致", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: [{ id: 1 }],
      page: { pageNum: 1, pageSize: 20, total: 1 },
    });

    // 直接复用共享包的类型守卫，避免契约与实现各写一份口径
    expect(isPageResult(res.data)).toBe(true);
    expect(Object.keys(res.data).sort()).toEqual(["list", "page", "page_size", "total"]);
  });

  it("普通对象含 data + page 但 page 非分页元信息时，不得被误判为分页", async () => {
    const payload = { data: { realPayload: 1 }, page: { theme: "dark" } };
    const res = await run(createInterceptor(), createContext(), payload);

    expect(res.data).toEqual(payload);
    expect(res.data).not.toHaveProperty("list");
    expect(res.data).not.toHaveProperty("page_size");
  });

  it("page 仅含非数字 total、无页码信息时，不判定为分页", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: [1, 2],
      page: { total: "30" },
    });

    expect(res.data.list).toBeUndefined();
    expect(res.data.page_size).toBeUndefined();
  });

  it("兼容历史命名：有 pageNum + pageSize 但缺 total 时仍识别为分页", async () => {
    const res = await run(createInterceptor(), createContext(), {
      data: [1, 2],
      page: { pageNum: 3, pageSize: 10 },
    });

    expect(res.data.list).toEqual([1, 2]);
    expect(res.data.total).toBe(0);
    expect(res.data.page).toBe(3);
    expect(res.data.page_size).toBe(10);
  });

  it("非分页载荷：原样包裹，不附加分页字段", async () => {
    const res = await run(createInterceptor(), createContext(), { id: 7, name: "豆豆" });

    expect(res.code).toBe("00000");
    expect(res.data).toEqual({ id: 7, name: "豆豆" });
    expect(res.data).not.toHaveProperty("list");
    expect(res.data).not.toHaveProperty("page_size");
  });

  it("标注 skipResponseTransform 时透传原始载荷", async () => {
    const res = await run(createInterceptor(true), createContext(), { raw: true });

    expect(res).toEqual({ raw: true });
  });
});

﻿import { CallHandler, ExecutionContext, Injectable, NestInterceptor } from "@nestjs/common";
import { Reflector } from "@nestjs/core";
import { Observable } from "rxjs";
import { map } from "rxjs/operators";
import { normalizePageQuery, type PageResult, type PageQuery } from "@peluvida/shared";
import { ErrorCode } from "../../common/enums/error-code.enum";
import { Response } from "../../common/interfaces/response.interface";
import { transformDatesInObject, DateFormatOptions } from "../../common/utils/serialize.util";
import { ConfigService } from "@nestjs/config";

/**
 * 业务层分页载荷：统一返回 `{ data, page }`
 * - `data` 为当前页数据
 * - `page` 为分页元信息，历史命名为 `pageNum / pageSize / total`
 */
interface PaginatedPayload<T = unknown> {
  data: T;
  page: {
    pageNum?: number;
    pageSize?: number;
    page?: number;
    page_size?: number;
    total?: number;
  };
}

/**
 * 判定 `page` 是否为分页元信息。
 *
 * 需要同时满足两点：既要**排除**「恰好也叫 page 的普通业务字段」
 * （否则 `{ data: xxx, page: { theme: "dark" } }` 会被误改写并丢失内容），
 * 又要**兼容**业务层的历史命名 `{ pageNum, pageSize, total }`。
 *
 * 判定规则：`total` 为数字，**或** 同时存在数字型页码与每页条数。
 *
 * ⚠️ 分页元信息必须是「数字」：字符串型（如 `{ pageNum: "1", pageSize: "20" }`）
 * 会被判为非分页而不做改写。当前业务层的分页 service 均返回数字，
 * 新增分页接口时请勿改成字符串，否则列表会静默失去 `list/total/page/page_size` 信封。
 */
function isPageMeta(value: unknown): value is PaginatedPayload["page"] {
  if (!value || typeof value !== "object") return false;

  const candidate = value as Record<string, unknown>;
  const hasNumericTotal = typeof candidate.total === "number";
  const hasPageNum = typeof candidate.pageNum === "number" || typeof candidate.page === "number";
  const hasPageSize =
    typeof candidate.pageSize === "number" || typeof candidate.page_size === "number";

  return hasNumericTotal || (hasPageNum && hasPageSize);
}

@Injectable()
export class ResponseInterceptor<T> implements NestInterceptor<T, Response<T>> {
  private readonly dateFormatOptions: DateFormatOptions;
  constructor(
    private readonly reflector: Reflector,
    configService?: ConfigService
  ) {
    this.dateFormatOptions = {
      format: configService?.get<string>("DATE_FORMAT") || "yyyy-MM-dd HH:mm:ss",
      timeZone: configService?.get<string>("TIME_ZONE") || "Asia/Shanghai",
    };
  }

  intercept(ctx: ExecutionContext, next: CallHandler): Observable<Response<T>> {
    const skip = this.reflector.getAllAndOverride<boolean>("skipResponseTransform", [
      ctx.getHandler(),
      ctx.getClass(),
    ]);
    if (skip) {
      return next.handle() as any;
    }

    return next.handle().pipe(
      map((data) => {
        // 分页接口：业务层统一返回 { data, page }
        // ⚠️ 判定需同时满足「含 data」+「page 是分页元信息（含数字 total）」，
        //    避免普通业务对象因恰好有 page 字段而被误改写。
        if (
          data &&
          typeof data === "object" &&
          Object.prototype.hasOwnProperty.call(data as any, "data") &&
          isPageMeta((data as any).page)
        ) {
          const payload = data as PaginatedPayload;
          const page = payload.page ?? {};
          const formattedData = transformDatesInObject(payload.data, this.dateFormatOptions);
          const query = this.resolvePageQuery(page, ctx);

          // 列表信封统一为 list / total / page / page_size
          // ⚠️ 决策 A4 / PEL-08：在既有 { list, total } 上「纯增量」补 page / page_size，
          //    不改变外层 code / msg / data 结构，存量前端读取 res.list / res.total 不受影响。
          const result: PageResult<unknown> = {
            list: Array.isArray(formattedData) ? formattedData : [],
            total: typeof page.total === "number" ? page.total : 0,
            page: query.page,
            page_size: query.page_size,
          };

          return {
            code: ErrorCode.SUCCESS.code,
            msg: ErrorCode.SUCCESS.msg,
            data: result as any,
          };
        }

        const formatted = transformDatesInObject(data, this.dateFormatOptions);
        return {
          code: ErrorCode.SUCCESS.code,
          msg: ErrorCode.SUCCESS.msg,
          data: formatted,
        };
      })
    );
  }

  /**
   * 解析分页参数：优先取业务层 page 元信息，其次回落到请求 query，最后用共享包默认值。
   * 复用 @peluvida/shared 的 normalizePageQuery，天然兼容 pageNum / pageSize 历史命名与 100 条上限。
   */
  private resolvePageQuery(
    page: PaginatedPayload["page"],
    ctx: ExecutionContext
  ): PageQuery {
    const request = ctx.switchToHttp().getRequest?.();
    const query = request?.query ?? {};

    return normalizePageQuery({
      page: page?.page ?? page?.pageNum ?? query.page ?? query.pageNum,
      page_size: page?.page_size ?? page?.pageSize ?? query.page_size ?? query.pageSize,
    });
  }
}

import { Injectable, NestMiddleware, Logger } from "@nestjs/common";
import { Request, Response, NextFunction } from "express";
import { RedisService } from "../redis/redis.service";
import { BusinessException } from "../exceptions/business.exception";
import { ErrorCode } from "../enums/error-code.enum";
import { LoggerUtils } from "../utils/logger.utils";

const DEFAULT_IP_LIMIT = 10;
const RATE_LIMIT_WINDOW_SEC = 1;
const RATE_LIMIT_KEY_PREFIX = "rate_limiter:ip:";

@Injectable()
export class RateLimitMiddleware implements NestMiddleware {
  private readonly logger = new Logger(RateLimitMiddleware.name);

  constructor(private readonly redisService: RedisService) {}

  async use(req: Request, res: Response, next: NextFunction) {
    // OPTIONS 预检请求跳过限流
    if (req.method === "OPTIONS") {
      return next();
    }

    const ip = LoggerUtils.parseClientIP(req);
    if (!ip) {
      return next();
    }

    try {
      const key = `${RATE_LIMIT_KEY_PREFIX}${ip}`;
      const count = await this.redisService.getClient().incr(key);

      if (count === 1) {
        await this.redisService.getClient().expire(key, RATE_LIMIT_WINDOW_SEC);
      }

      if (count > DEFAULT_IP_LIMIT) {
        throw new BusinessException({
          code: ErrorCode.REQUEST_CONCURRENCY_LIMIT_EXCEEDED.code,
          msg: ErrorCode.REQUEST_CONCURRENCY_LIMIT_EXCEEDED.msg,
          httpStatus: 429,
        });
      }
    } catch (error) {
      if (error instanceof BusinessException) {
        throw error;
      }
      this.logger.warn("Redis 限流检查异常，跳过限流");
    }

    next();
  }

}

﻿import { Injectable, NestMiddleware } from "@nestjs/common";
import { randomUUID } from "crypto";
import { RequestContext } from "../context/request-context";

/**
 * 请求上下文中间件
 * 初始化 AsyncLocalStorage 上下文，确保数据权限系统正常工作
 *
 * CROSS-14：请求入口同源生成/透传 trace_id ——
 *  - `X-Trace-Id` 请求头优先（网关 / 上游服务已生成时保持全链路一致）；
 *  - 否则生成 UUID；
 *  - 写回响应头 `X-Trace-Id`，客户端报障时可携带该值精确定位本次请求的全链路日志。
 * trace_id 随后可从 `RequestContext.getTraceId()` 读取，winston 的
 * trace-context format 会自动注入每条日志（业务代码零感知）。
 */
@Injectable()
export class RequestContextMiddleware implements NestMiddleware {
  use(req: any, res: any, next: () => void) {
    RequestContext.run(() => {
      const incoming = req?.headers?.["x-trace-id"];
      const traceId =
        typeof incoming === "string" && incoming.trim() !== ""
          ? incoming.trim().slice(0, 64)
          : randomUUID();
      RequestContext.setTraceId(traceId);
      try {
        res?.setHeader?.("X-Trace-Id", traceId);
      } catch {
        // 响应头写入失败不影响主流程（如 SSE 场景头已发出）
      }
      next();
    });
  }
}

import { DataScopeEnum } from "../enums/data-scope.enum";
import { RoleDataScope } from "../models/role-data-scope.model";
import {
  buildDataScopeWhere,
  needsSubtreeDeptIds,
  type DataScopeSubject,
} from "./data-scope.extension";

/**
 * 数据权限编译器单测（PEL-10c）
 *
 * `buildDataScopeWhere` 是纯函数（不读上下文、不碰数据库），
 * 因此这里可以穷举边界，不需要起 PG / Redis。
 */

const CFG_USER = { deptField: "deptId", ownerField: "createBy" };

function subject(over: Partial<DataScopeSubject> = {}): DataScopeSubject {
  return {
    userId: "7",
    deptId: "3",
    isRoot: false,
    dataScopes: [],
    ...over,
  };
}

const ALL_FALSE_KEYS = (where: any) => Object.keys(where ?? {});

describe("buildDataScopeWhere（数据权限 → Prisma where 编译）", () => {
  describe("短路：不施加任何限制", () => {
    it("超级管理员直接放行", () => {
      expect(buildDataScopeWhere(CFG_USER, subject({ isRoot: true }))).toBeNull();
    });

    it("未登录（无 userId）放行 —— 与原实现一致", () => {
      expect(buildDataScopeWhere(CFG_USER, subject({ userId: null }))).toBeNull();
    });

    it("任一角色为「全部数据」即放行", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ dataScopes: [RoleDataScope.self("EMP"), RoleDataScope.all("ROOT")] })
      );
      expect(where).toBeNull();
    });

    it("两个维度都没声明时放行（无从表达限制，交由权限守卫处理）", () => {
      expect(
        buildDataScopeWhere({}, subject({ dataScopes: [RoleDataScope.self("EMP")] }))
      ).toBeNull();
    });
  });

  describe("fail-closed：编译不出条件时拒绝而非放行", () => {
    it("无任何角色数据范围 → 恒假", () => {
      const where = buildDataScopeWhere(CFG_USER, subject({ dataScopes: [] }));
      expect(where).toEqual({ deptId: { in: [] } });
    });

    it("仅有「本部门」范围但用户 deptId 缺失 → 恒假", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ deptId: null, dataScopes: [RoleDataScope.dept("MGR")] })
      );
      expect(where).toEqual({ deptId: { in: [] } });
    });

    it("仅有「本人」范围但 ownerField 未声明 → 恒假", () => {
      const where = buildDataScopeWhere(
        { deptField: "deptId" },
        subject({ dataScopes: [RoleDataScope.self("EMP")] })
      );
      expect(where).toEqual({ deptId: { in: [] } });
    });

    it("自定义范围但一个部门都没勾 → 恒假", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ dataScopes: [RoleDataScope.custom("CU", [])] })
      );
      expect(where).toEqual({ deptId: { in: [] } });
    });
  });

  describe("单角色：各数据范围的条件形态", () => {
    it("本部门 → 部门字段等值（BigInt）", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ deptId: "3", dataScopes: [RoleDataScope.dept("MGR")] })
      );
      expect(where).toEqual({ deptId: 3n });
    });

    it("仅本人 → 归属人字段等值（BigInt）", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ userId: "7", dataScopes: [RoleDataScope.self("EMP")] })
      );
      expect(where).toEqual({ createBy: 7n });
    });

    it("自定义部门 → 部门字段 IN 列表", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ dataScopes: [RoleDataScope.custom("CU", [1, 2, 3])] })
      );
      expect(where).toEqual({ deptId: { in: [1n, 2n, 3n] } });
    });

    it("本部门及子部门 → 部门字段 IN 预解析子树", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({
          dataScopes: [RoleDataScope.deptAndSub("MGR")],
          subtreeDeptIds: ["1", "2", "9"],
        })
      );
      expect(where).toEqual({ deptId: { in: [1n, 2n, 9n] } });
    });

    it("单分支时直接返回该分支，不额外包一层 OR", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ dataScopes: [RoleDataScope.dept("MGR")] })
      );
      expect(ALL_FALSE_KEYS(where)).not.toContain("OR");
    });
  });

  describe("多角色：并集（OR）语义", () => {
    it("「本部门」+「仅本人」→ OR 两支", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({
          userId: "7",
          deptId: "3",
          dataScopes: [RoleDataScope.dept("MGR"), RoleDataScope.self("EMP")],
        })
      );
      expect(where).toEqual({ OR: [{ deptId: 3n }, { createBy: 7n }] });
    });

    it("部分角色不产生条件时，只保留有效分支（不因此放行）", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({
          deptId: null, // 让 DEPT 分支失效
          dataScopes: [RoleDataScope.dept("MGR"), RoleDataScope.self("EMP")],
        })
      );
      expect(where).toEqual({ createBy: 7n });
    });

    it("两支都失效 → 恒假（不能因为「都没条件」而放行）", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({
          userId: "7",
          deptId: null,
          dataScopes: [RoleDataScope.dept("MGR"), RoleDataScope.deptAndSub("MGR2")],
        })
      );
      expect(where).toEqual({ deptId: { in: [] } });
    });
  });

  describe("取值健壮性", () => {
    it("userId / deptId 非数字时视为缺失（不抛错）", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({
          userId: "abc",
          deptId: "not-a-number",
          dataScopes: [RoleDataScope.self("EMP"), RoleDataScope.dept("MGR")],
        })
      );
      expect(where).toEqual({ deptId: { in: [] } });
    });

    it("自定义部门 ID 里混入非法值时只保留合法项", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ dataScopes: [RoleDataScope.custom("CU", [1, "x" as unknown as number, 2])] })
      );
      expect(where).toEqual({ deptId: { in: [1n, 2n] } });
    });

    it("子树 id 为空数组时该分支失效", () => {
      const where = buildDataScopeWhere(
        CFG_USER,
        subject({ dataScopes: [RoleDataScope.deptAndSub("MGR")], subtreeDeptIds: [] })
      );
      expect(where).toEqual({ deptId: { in: [] } });
    });
  });

  describe("枚举口径一致性（防与 shared 包漂移）", () => {
    it("DataScopeEnum 的取值与 product 约定一致", () => {
      expect(DataScopeEnum.ALL).toBe(1);
      expect(DataScopeEnum.DEPT_AND_SUB).toBe(2);
      expect(DataScopeEnum.DEPT).toBe(3);
      expect(DataScopeEnum.SELF).toBe(4);
      expect(DataScopeEnum.CUSTOM).toBe(5);
    });

    it("needsSubtreeDeptIds 只为 DEPT_AND_SUB 返回 true", () => {
      expect(needsSubtreeDeptIds([])).toBe(false);
      expect(needsSubtreeDeptIds([RoleDataScope.all("R")])).toBe(false);
      expect(needsSubtreeDeptIds([RoleDataScope.dept("R")])).toBe(false);
      expect(needsSubtreeDeptIds([RoleDataScope.self("R")])).toBe(false);
      expect(needsSubtreeDeptIds([RoleDataScope.custom("R", [1])])).toBe(false);
      expect(needsSubtreeDeptIds([RoleDataScope.deptAndSub("R")])).toBe(true);
      expect(needsSubtreeDeptIds([RoleDataScope.all("R"), RoleDataScope.deptAndSub("R2")])).toBe(
        true
      );
    });
  });
});

import { DEFAULT_TTL_SECONDS } from "@peluvida/shared";
import { RedisService } from "./redis.service";
import { RequestContext } from "../context/request-context";

describe("CROSS-10 · RedisService 默认 TTL（键规范）", () => {
  function makeService() {
    const calls: Array<{ cmd: string; args: unknown[] }> = [];
    const client = {
      setex: (...args: unknown[]) => {
        calls.push({ cmd: "setex", args });
        return "OK";
      },
      set: (...args: unknown[]) => {
        calls.push({ cmd: "set", args });
        return "OK";
      },
    };
    const svc = new RedisService({ getOrThrow: () => client } as never);
    return { svc, calls };
  }

  it("不传 ttl 时落默认 1h（setex 3600）", async () => {
    const { svc, calls } = makeService();
    await svc.set("demo:key", 1);
    expect(calls[0].cmd).toBe("setex");
    expect(calls[0].args[1]).toBe(DEFAULT_TTL_SECONDS);
  });

  it("显式 ttl 覆盖默认值", async () => {
    const { svc, calls } = makeService();
    await svc.set("demo:key", 1, 120);
    expect(calls[0].cmd).toBe("setex");
    expect(calls[0].args[1]).toBe(120);
  });

  it("非法 ttl（0/负数）也落默认值", async () => {
    const { svc, calls } = makeService();
    await svc.set("demo:key", 1, 0);
    await svc.set("demo:key", 1, -5);
    expect(calls[0].args[1]).toBe(DEFAULT_TTL_SECONDS);
    expect(calls[1].args[1]).toBe(DEFAULT_TTL_SECONDS);
  });

  it("租户上下文下键名仍自动加 tenant: 前缀（PEL-11 行为不变）", async () => {
    const { svc, calls } = makeService();
    RequestContext.run(async () => {
      RequestContext.setTenantId("900042");
      await svc.set("demo:key", 1);
    });
    expect(String(calls[0].args[0])).toBe("tenant:900042:demo:key");
  });
});

﻿import { Injectable, Logger } from "@nestjs/common";
import { RedisService as LiaoliaRedisService } from "@liaoliaots/nestjs-redis";
import type { Redis } from "ioredis";
import { DEFAULT_TTL_SECONDS } from "@peluvida/shared";
import { RequestContext } from "../context/request-context";
import { TENANT_REDIS_PREFIX } from "../../tenant/tenant.constants";

/**
 * Redis 服务（缓存抽象，基于 ioredis）
 *
 * 提供常用的缓存操作方法，支持：
 * - 基础 KV 操作（set/get/del）
 * - Hash 操作（hset/hget/hdel/hmget）
 * - 模式匹配删除
 *
 * **多租户键前缀（PEL-11）**：当前请求上下文带租户ID 时，所有键自动改写为
 * `tenant:<租户ID>:<原键>`（决策 A2：Redis 键带 `tenant:` 前缀）；无租户上下文
 * （平台级缓存、未登录请求、定时任务）保持原键，行为与历史完全一致。
 * 租户ID 唯一来源是 JWT → RequestContext，**不接受业务代码显式传入**。
 */
@Injectable()
export class RedisService {
  private readonly client: Redis;
  private readonly logger = new Logger(RedisService.name);

  constructor(private redisService: LiaoliaRedisService) {
    this.client = this.redisService.getOrThrow();
  }

  /**
   * 按当前租户上下文改写键名：
   * `key` → `tenant:<tenantId>:key`（有租户上下文时），否则原样返回。
   */
  private resolveKey(key: string): string {
    const tenantId = RequestContext.getTenantId();
    return tenantId ? `${TENANT_REDIS_PREFIX}${tenantId}:${key}` : key;
  }

  /**
   * 获取原生 Redis 客户端（用于特殊操作如 incr/expire）
   *
   * ⚠️ 走原生客户端的键**不会**自动加租户前缀；租户范围的键请用本服务的方法，
   * 或显式调用 `scopedKey()` 后再操作。
   */
  getClient(): Redis {
    return this.client;
  }

  /** 显式按当前租户上下文改写键名（供原生客户端特殊操作时对齐前缀规则） */
  scopedKey(key: string): string {
    return this.resolveKey(key);
  }

  /**
   * 写入缓存（CROSS-10 键规范：默认 TTL 1h）
   *
   * 不传 `ttl` 或传非正数时落 {@link DEFAULT_TTL_SECONDS}（1 小时）——
   * 防止无主键堆积；存量调用全部显式传 TTL，行为不变。
   * 需要永不过期的键（极少数）请走 `getClient()` 原生 set 并在键名审计中登记。
   */
  async set(key: string, value: any, ttl?: number): Promise<boolean> {
    try {
      const serialized = JSON.stringify(value);
      const resolved = this.resolveKey(key);
      const effectiveTtl = ttl && ttl > 0 ? ttl : DEFAULT_TTL_SECONDS;
      await this.client.setex(resolved, effectiveTtl, serialized);
      return true;
    } catch (err) {
      this.logger.error("Redis set error", err);
      return false;
    }
  }

  async get<T = any>(key: string): Promise<T | null> {
    try {
      const data = await this.client.get(this.resolveKey(key));
      return data ? JSON.parse(data) : null;
    } catch (err) {
      this.logger.error("Redis get error", err);
      return null;
    }
  }

  async del(key: string): Promise<boolean> {
    try {
      const result = await this.client.del(this.resolveKey(key));
      return result === 1;
    } catch (err) {
      this.logger.error("Redis delete error", err);
      return false;
    }
  }

  async delMultiple(keys: string[]): Promise<number> {
    try {
      if (keys.length === 0) return 0;
      return await this.client.del(...keys.map((k) => this.resolveKey(k)));
    } catch (err) {
      this.logger.error("Redis bulk delete error", err);
      return 0;
    }
  }

  async deletePattern(pattern: string): Promise<number> {
    try {
      // KEYS 返回的已是带前缀的物理键名（resolveKey 已应用），必须用原生客户端直删；
      // 不能走 delMultiple —— 它会对键名再次前缀，导致删到不存在的键（返回 0）
      const keys = await this.client.keys(this.resolveKey(pattern));
      if (keys.length === 0) return 0;
      return await this.client.del(...keys);
    } catch (err) {
      this.logger.error("Redis pattern delete error", err);
      return 0;
    }
  }

  async hasKey(key: string): Promise<boolean> {
    try {
      const result = await this.client.exists(this.resolveKey(key));
      return result === 1;
    } catch (err) {
      this.logger.error("Redis exists check error", err);
      return false;
    }
  }

  /**
   * 设置 Hash 字段值
   *
   * @param key Hash 键名
   * @param field 字段名
   * @param value 字段值（自动 JSON 序列化）
   */
  async hset(key: string, field: string, value: any): Promise<boolean> {
    try {
      const serialized = JSON.stringify(value);
      await this.client.hset(this.resolveKey(key), field, serialized);
      return true;
    } catch (err) {
      this.logger.error("Redis hset error", err);
      return false;
    }
  }

  /**
   * 获取 Hash 字段值
   *
   * @param key Hash 键名
   * @param field 字段名
   * @returns 字段值（自动 JSON 反序列化），不存在返回 null
   */
  async hget<T = any>(key: string, field: string): Promise<T | null> {
    try {
      const data = await this.client.hget(this.resolveKey(key), field);
      return data ? JSON.parse(data) : null;
    } catch (err) {
      this.logger.error("Redis hget error", err);
      return null;
    }
  }

  /**
   * 删除 Hash 字段
   *
   * @param key Hash 键名
   * @param fields 要删除的字段名（支持多个）
   * @returns 删除的字段数量
   */
  async hdel(key: string, ...fields: string[]): Promise<number> {
    try {
      if (fields.length === 0) return 0;
      return await this.client.hdel(this.resolveKey(key), ...fields);
    } catch (err) {
      this.logger.error("Redis hdel error", err);
      return 0;
    }
  }

  /**
   * 批量获取 Hash 字段值
   *
   * @param key Hash 键名
   * @param fields 字段名列表
   * @returns 字段值数组，顺序与 fields 对应，不存在的字段为 null
   */
  async hmget<T = any>(key: string, fields: string[]): Promise<(T | null)[]> {
    try {
      if (fields.length === 0) return [];
      const results = await this.client.hmget(this.resolveKey(key), ...fields);
      return results.map((data) => (data ? JSON.parse(data) : null));
    } catch (err) {
      this.logger.error("Redis hmget error", err);
      return fields.map(() => null);
    }
  }

  /**
   * 删除整个 Hash 键
   *
   * @param key Hash 键名
   */
  async delHash(key: string): Promise<boolean> {
    return this.del(key);
  }

  /**
   * 检查 Hash 字段是否存在
   *
   * @param key Hash 键名
   * @param field 字段名
   */
  async hexists(key: string, field: string): Promise<boolean> {
    try {
      const result = await this.client.hexists(this.resolveKey(key), field);
      return result === 1;
    } catch (err) {
      this.logger.error("Redis hexists error", err);
      return false;
    }
  }
}

﻿import type { Request, Response } from "express";
import type { IncomingHttpHeaders } from "http";

interface RequestLogContext {
  url: string;
  method: string;
  clientIP: string;
  userAgent?: string;
  referrer?: string;
  params: Record<string, unknown>;
  query: Record<string, unknown>;
  /** 脱敏后的请求头（键级打码后不再是 IncomingHttpHeaders 原始形状） */
  headers: Record<string, unknown>;
  body: Record<string, unknown>;
}

interface ResponseLogContext {
  statusCode: number;
  latency: number;
  contentLength?: number;
}

/** 触发键级脱敏的键名（小写匹配，含常见别名的超集；CROSS-14） */
const SENSITIVE_KEY_PATTERNS: RegExp[] = [
  /pass(word)?/,
  /token/,
  /secret/,
  /authorization/,
  /cookie/,
  /id_?card/,
  /captcha/,
  /credit_?card/,
  /mobile/,
  /phone/,
  /email/,
];

/** 中国大陆手机号（值级脱敏）：138****5678 */
const CN_MOBILE_RE = /(?<!\d)1[3-9]\d{9}(?!\d)/g;

/** 身份证 18 位（值级脱敏）：前 6 后 2 保留 */
const CN_ID_CARD_RE = /(?<!\d)\d{17}[\dXx](?!\d)/g;

export class LoggerUtils {
  static captureRequestContext(req: Request): RequestLogContext {
    return {
      url: req.originalUrl,
      method: req.method,
      clientIP: this.parseClientIP(req),
      userAgent: req.headers["user-agent"],
      referrer: req.headers.referer,
      params: req.params as Record<string, unknown>,
      query: this.maskSensitive(req.query as Record<string, unknown>),
      headers: this.maskSensitive(req.headers as Record<string, unknown>),
      body: this.maskSensitive(req.body as Record<string, unknown>),
    };
  }

  static captureResponseContext(res: Response, startTime: number): ResponseLogContext {
    return {
      statusCode: res.statusCode,
      latency: Date.now() - startTime,
      contentLength: res.getHeader("content-length") as number,
    };
  }

  static parseClientIP(req: Request): string {
    return (
      req.ip || req.socket?.remoteAddress || req.headers["x-forwarded-for"]?.toString() || "unknown"
    );
  }

  /**
   * 递归脱敏（CROSS-14 结构化日志）：
   *  1. **键级** —— 键名命中 {@link SENSITIVE_KEY_PATTERNS} 时整值替换为 `***`；
   *  2. **值级** —— 字符串值里的手机号 `138****5678`、身份证号（前6后2）脱敏。
   * 原对象不被修改（返回深拷贝）；循环引用按 `[Circular]` 处理。
   */
  static maskSensitive<T>(value: T, depth = 0, seen = new WeakSet<object>()): T {
    if (value === null || typeof value !== "object" || depth > 6) {
      return this.maskStringified(value);
    }
    if (seen.has(value as object)) return "[Circular]" as unknown as T;
    seen.add(value as object);

    if (Array.isArray(value)) {
      return value.map((item) => this.maskSensitive(item, depth + 1, seen)) as unknown as T;
    }

    const out: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(value as Record<string, unknown>)) {
      if (SENSITIVE_KEY_PATTERNS.some((re) => re.test(key.toLowerCase()))) {
        out[key] = "***";
      } else {
        out[key] = this.maskSensitive(val, depth + 1, seen);
      }
    }
    return out as unknown as T;
  }

  /** 原始值的值级脱敏：手机号 / 身份证号出现在任意字符串中时打码 */
  private static maskStringified<T>(value: T): T {
    if (typeof value !== "string") return value;
    return value
      .replace(CN_MOBILE_RE, (m) => m.slice(0, 3) + "****" + m.slice(7))
      .replace(CN_ID_CARD_RE, (m) => m.slice(0, 6) + "********" + m.slice(-2)) as unknown as T;
  }
}

﻿export type DateFormatOptions = {
  /** 格式模式，当前支持 'yyyy-MM-dd HH:mm:ss' */
  format?: string;
  /** IANA 时区标识，如 'Asia/Shanghai' */
  timeZone?: string;
};

export function formatDateToString(date: Date, opts?: DateFormatOptions): string | null {
  if (!(date instanceof Date)) return null;
  const timeZone = opts?.timeZone || "Asia/Shanghai";

  // 使用 Intl.DateTimeFormat 获取指定时区的各时间部分，再拼接为字符串
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone,
    hour12: false,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(date);

  const get = (type: string) => parts.find((p) => p.type === type)?.value || "";
  const y = get("year");
  const m = get("month");
  const d = get("day");
  const hh = get("hour");
  const mm = get("minute");
  const ss = get("second");

  // 返回常见格式 'yyyy-MM-dd HH:mm:ss'
  return `${y}-${m}-${d} ${hh}:${mm}:${ss}`;
}

function isPlainObject(value: any): boolean {
  return Object.prototype.toString.call(value) === "[object Object]";
}

export function transformDatesInObject<T>(obj: T, opts?: DateFormatOptions): T {
  if (obj === null || obj === undefined) return obj;

  if (obj instanceof Date) {
    return formatDateToString(obj, opts) as unknown as T;
  }

  if (typeof obj === "bigint") {
    return obj.toString() as unknown as T;
  }

  if (typeof obj === "number") {
    if (!Number.isSafeInteger(obj)) {
      return obj.toString() as unknown as T;
    }
    return obj;
  }

  if (Array.isArray(obj)) {
    return obj.map((item) => transformDatesInObject(item, opts)) as unknown as T;
  }

  if (isPlainObject(obj)) {
    const res: any = {};
    for (const key of Object.keys(obj as any)) {
      const val = (obj as any)[key];
      // Date -> 格式化字符串
      if (val instanceof Date) {
        res[key] = formatDateToString(val, opts);
        continue;
      }

      // BigInt -> 字符串
      if (typeof val === "bigint") {
        res[key] = val.toString();
        continue;
      }

      // 超出安全整数范围的 Number -> 字符串
      if (typeof val === "number" && !Number.isSafeInteger(val)) {
        res[key] = val.toString();
        continue;
      }

      // 嵌套数组 / 对象 -> 递归处理
      if (Array.isArray(val) || isPlainObject(val)) {
        res[key] = transformDatesInObject(val, opts);
        continue;
      }

      // 其他类型直接透传
      res[key] = val;
    }
    return res;
  }

  return obj;
}

/**
 * 启动期环境变量校验（CROSS-06 环境配置规范）
 *
 * 挂载方式：ConfigModule.forRoot({ validate: validateEnv })
 *
 * 设计要点：
 * 1. fail-fast 且一次性列出全部问题——启动即报错，逐条给出「变量名 + 含义 + 原因」；
 * 2. 零依赖纯函数，仅做结构级检查（非空 / 数字 / 枚举 / 长度），不做连通性探测；
 * 3. config 各 registerAs 工厂内的 required 兜底（如 database.config.ts）保留为第二道防线；
 * 4. 未提供且有业务默认值的变量（SESSION_TYPE=jwt / OSS_TYPE=aliyun）放行，不改变现有行为；
 * 5. 返回原 config（不做默认值注入），避免改变 ConfigService 的既有读取结果。
 */

type Env = Record<string, unknown>;

interface RequiredRule {
  key: string;
  label: string;
}

interface EnumRule extends RequiredRule {
  values: string[];
  /** 未提供时的业务默认值；有默认值的变量缺失时放行 */
  fallback?: string;
}

interface NumberRule extends RequiredRule {
  integer?: boolean;
  min?: number;
}

/** 无条件必需的变量 */
const REQUIRED_KEYS: RequiredRule[] = [
  { key: "NODE_ENV", label: "运行环境" },
  { key: "APP_PORT", label: "应用监听端口" },
  { key: "PG_HOST", label: "数据库主机" },
  { key: "PG_PORT", label: "数据库端口" },
  { key: "PG_USER", label: "数据库账号" },
  { key: "PG_PASSWORD", label: "数据库密码" },
  { key: "PG_DB", label: "数据库名称" },
  { key: "REDIS_HOST", label: "Redis 主机" },
  { key: "REDIS_PORT", label: "Redis 端口" },
  { key: "JWT_SECRET_KEY", label: "JWT 签名密钥" },
  { key: "JWT_EXPIRES_IN", label: "JWT 过期时间(秒)" },
  { key: "JWT_ISSUER", label: "JWT 签发方标识" },
];

/** 枚举约束变量 */
const ENUM_RULES: EnumRule[] = [
  { key: "NODE_ENV", label: "运行环境", values: ["dev", "prod", "test"] },
  { key: "SESSION_TYPE", label: "会话类型", values: ["jwt", "redis-token"], fallback: "jwt" },
  { key: "OSS_TYPE", label: "对象存储类型", values: ["aliyun", "minio", "local"], fallback: "aliyun" },
];

/** 数字约束变量（仅在提供了值时校验格式） */
const NUMBER_RULES: NumberRule[] = [
  { key: "APP_PORT", label: "应用监听端口", integer: true, min: 1 },
  { key: "PG_PORT", label: "数据库端口", integer: true, min: 1 },
  { key: "REDIS_PORT", label: "Redis 端口", integer: true, min: 1 },
  { key: "JWT_EXPIRES_IN", label: "JWT 过期时间(秒)", integer: true, min: 1 },
  { key: "AI_TIMEOUT_MS", label: "AI 请求超时(毫秒)", integer: true, min: 1 },
];

/** OSS_TYPE 条件必填映射（选了哪种存储，哪组的连接参数就必填） */
const OSS_TYPE_REQUIREMENTS: Record<string, RequiredRule[]> = {
  minio: [
    { key: "OSS_MINIO_ENDPOINT", label: "MinIO Endpoint" },
    { key: "OSS_MINIO_ACCESS_KEY", label: "MinIO AccessKey" },
    { key: "OSS_MINIO_SECRET_KEY", label: "MinIO SecretKey" },
    { key: "OSS_MINIO_BUCKET", label: "MinIO Bucket" },
  ],
  aliyun: [
    { key: "OSS_ALIYUN_ENDPOINT", label: "阿里云 Endpoint" },
    { key: "OSS_ALIYUN_ACCESS_KEY_ID", label: "阿里云 AccessKeyId" },
    { key: "OSS_ALIYUN_ACCESS_KEY_SECRET", label: "阿里云 AccessKeySecret" },
    { key: "OSS_ALIYUN_BUCKET", label: "阿里云 Bucket" },
  ],
  local: [{ key: "OSS_LOCAL_STORAGE_PATH", label: "本地存储路径" }],
};

/** HS256 安全基线：密钥至少 32 字符 */
const JWT_SECRET_MIN_LENGTH = 32;

function asTrimmedString(config: Env, key: string): string {
  const value = config[key];
  if (typeof value === "string") return value.trim();
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

export function validateEnv(config: Env): Env {
  const errors: string[] = [];

  // 1) 无条件必需
  for (const { key, label } of REQUIRED_KEYS) {
    if (!asTrimmedString(config, key)) {
      errors.push(`缺少必需变量 ${key}（${label}）`);
    }
  }

  // 2) 枚举约束
  for (const rule of ENUM_RULES) {
    const value = asTrimmedString(config, rule.key);
    if (!value && rule.fallback !== undefined) continue; // 未提供且有默认值 → 放行
    if (value && !rule.values.includes(value)) {
      errors.push(`${rule.key}（${rule.label}）取值非法「${value}」，允许：${rule.values.join(" | ")}`);
    }
  }

  // 3) 数字约束（仅对已提供的值做格式检查）
  for (const rule of NUMBER_RULES) {
    const value = asTrimmedString(config, rule.key);
    if (!value) continue;
    const num = Number(value);
    if (!Number.isFinite(num) || (rule.integer && !Number.isInteger(num))) {
      errors.push(`${rule.key}（${rule.label}）必须是${rule.integer ? "整数" : "数字"}，当前值「${value}」`);
    } else if (rule.min !== undefined && num < rule.min) {
      errors.push(`${rule.key}（${rule.label}）不能小于 ${rule.min}，当前值「${value}」`);
    }
  }

  // 4) JWT 密钥强度
  const secret = asTrimmedString(config, "JWT_SECRET_KEY");
  if (secret && secret.length < JWT_SECRET_MIN_LENGTH) {
    errors.push(
      `JWT_SECRET_KEY（JWT 签名密钥）长度不足：HS256 要求至少 ${JWT_SECRET_MIN_LENGTH} 字符，当前 ${secret.length} 字符`,
    );
  }

  // 5) OSS 条件必填
  const ossType = asTrimmedString(config, "OSS_TYPE") || "aliyun";
  const ossRequirements = OSS_TYPE_REQUIREMENTS[ossType];
  if (ossRequirements) {
    for (const { key, label } of ossRequirements) {
      if (!asTrimmedString(config, key)) {
        errors.push(`OSS_TYPE=${ossType} 时缺少必需变量 ${key}（${label}）`);
      }
    }
  }

  if (errors.length > 0) {
    throw new Error(
      [
        `[Env Validation] 环境变量校验失败，共 ${errors.length} 项：`,
        ...errors.map((e) => `  - ${e}`),
        `请检查 .env / .env.<NODE_ENV> 文件或启动注入的环境变量（参见 .env.example）`,
      ].join("\n"),
    );
  }

  return config;
}

﻿import { Controller, Delete, Post, Query, UploadedFile, UseInterceptors } from "@nestjs/common";
import { FileInterceptor } from "@nestjs/platform-express";
import { ApiOperation, ApiTags } from "@nestjs/swagger";
import { FileService } from "./file.service";

/**
 * 文件接口控制器
 * 提供简单的文件上传/删除功能
 */
@ApiTags("10.文件接口")
@Controller("files")
export class FileController {
  constructor(private readonly fileService: FileService) {}

  @ApiOperation({ summary: "上传文件" })
  @Post()
  @UseInterceptors(FileInterceptor("file"))
  async upload(@UploadedFile() file: any) {
    return await this.fileService.uploadFile(file);
  }

  @ApiOperation({ summary: "删除文件" })
  @Delete()
  async delete(@Query("filePath") filePath?: string) {
    return await this.fileService.deleteFile(filePath);
  }
}

﻿import { Injectable, Inject } from "@nestjs/common";

import * as dayjs from "dayjs";
import { ConfigType } from "@nestjs/config";
import ossConfig from "../config/oss.config";
import OSS, * as Client from "ali-oss";
import * as Minio from "minio";
import * as $OpenApi from "@alicloud/openapi-client";
import ocr_api20210707, * as $ocr_api20210707 from "@alicloud/ocr-api20210707";
import Util, * as $Util from "@alicloud/tea-util";
import { v4 as uuidv4 } from "uuid";
import * as fs from "fs";
import * as path from "path";

/**
 * 文件服务（OSS/MinIO/本地存储）
 */
@Injectable()
export class FileService {
  /** 当前 OSS 类型：aliyun | minio | local */
  private readonly ossType: "aliyun" | "minio" | "local";

  /** 阿里云 OSS 客户端 */
  private aliClient: OSS;
  private aliConfig: OSS.Options & { bucket: string };
  private staticClient: OSS;
  private staticConfig: OSS.Options & { bucket: string };

  /** MinIO 客户端及配置（当 ossType=minio 时启用） */
  private minioClient: Minio.Client | null = null;
  private minioBucket: string | null = null;
  private minioConfig: Minio.ClientOptions = {} as Minio.ClientOptions;

  // OCR 身份证识别（阿里云）
  private OCRClient: ocr_api20210707 | null = null;
  private OCRConfig: $OpenApi.Config = new $OpenApi.Config({});

  constructor(
    @Inject(ossConfig.KEY)
    private readonly ossConf: ConfigType<typeof ossConfig>
  ) {
    this.ossType = ossConf.type;

    // 阿里云 OSS 初始化
    if (this.ossType === "aliyun") {
      const ali = ossConf.aliyun;

      this.aliConfig = {
        region: ali.endpoint, // ali-oss 里 region 可用 endpoint 配置
        accessKeyId: ali.accessKeyId,
        accessKeySecret: ali.accessKeySecret,
        secure: true,
        bucket: ali.bucketName,
        callbackUrl: "http://localhost:3000/oss/result",
      };
      this.aliClient = new Client(this.aliConfig);

      this.staticConfig = {
        region: ali.endpoint,
        accessKeyId: ali.accessKeyId,
        accessKeySecret: ali.accessKeySecret,
        bucket: "staticolgstorage",
        callbackUrl: "http://localhost:3000/oss/result",
      };
      this.staticClient = new Client(this.staticConfig);

      this.OCRConfig = new $OpenApi.Config({
        accessKeyId: ali.accessKeyId,
        accessKeySecret: ali.accessKeySecret,
        endpoint: ali.endpoint,
      });
      this.OCRClient = new ocr_api20210707(this.OCRConfig);
    }

    // MinIO 初始化
    if (this.ossType === "minio") {
      const minio = ossConf.minio;

      // 解析 endpoint
      const url = new URL(minio.endpoint);
      const endPoint = url.hostname;
      const port = Number(url.port) || (url.protocol === "https:" ? 443 : 9000);
      const useSSL = url.protocol === "https:";

      this.minioConfig = {
        endPoint,
        port,
        useSSL,
        accessKey: minio.accessKey,
        secretKey: minio.secretKey,
      };

      this.minioClient = new Minio.Client(this.minioConfig);
      this.minioBucket = minio.bucketName;
    }
  }

  //  定义两个存储桶连接
  async getSignature() {
    // 阿里云 OSS：保持原有签名行为
    if (this.ossType === "aliyun") {
      const date = new Date();
      date.setDate(date.getDate() + 1);

      const policy = {
        expiration: date.toISOString(),
        conditions: [["content-length-range", 0, 10485760000]],
      };

      const formData = await this.aliClient.calculatePostSignature(policy);
      const location = await this.aliClient.getBucketLocation(this.aliConfig.bucket);
      const host = `https://${this.aliConfig.bucket}.${location.location}.aliyuncs.com`;

      const callback = {
        callbackUrl: this.aliConfig.callbackUrl,
        callbackBody:
          "filename=${object}&size=${size}&mimeType=${mimeType}&height=${imageInfo.height}&width=${imageInfo.width}",
        callbackBodyType: "application/x-www-form-urlencoded",
      };

      return {
        expire: dayjs().add(1, "days").unix().toString(),
        policy: formData.policy,
        signature: formData.Signature,
        accessId: formData.OSSAccessKeyId,
        host,
        dir: this.aliConfig.dir,
        callback: Buffer.from(JSON.stringify(callback)).toString("base64"),
      };
    }

    // MinIO：返回预签名上传 URL（PUT），前端直接向该 URL 上传文件
    if (this.ossType === "minio" && this.minioClient && this.minioBucket) {
      const objectPrefix = `uploads/${dayjs().format("YYYY/MM/DD")}/`;
      const objectName = `${objectPrefix}`; // 前端需要自行替换为具体文件名

      // 预签名 URL 有效期（秒）
      const expires = 24 * 60 * 60;
      const uploadUrl = await this.minioClient.presignedPutObject(
        this.minioBucket,
        objectName,
        expires
      );

      return {
        type: "minio",
        bucket: this.minioBucket,
        objectPrefix,
        uploadUrl,
        expires,
      };
    }

    // 其他类型（local）暂不提供前端直传签名
    return {
      type: this.ossType,
      message: "current OSS type does not support direct upload signature",
    };
  }

  async getstaticSignature() {
    const date = new Date();
    date.setDate(date.getDate() + 1);

    const policy = {
      expiration: date.toISOString(),
      conditions: [["content-length-range", 0, 10485760000]],
    };

    const formData = await this.staticClient.calculatePostSignature(policy);
    const location = await this.staticClient.getBucketLocation("staticolgstorage");
    const host = `https://${this.staticConfig.bucket}.${location.location}.aliyuncs.com`;

    const callback = {
      callbackUrl: this.staticConfig.callbackUrl,
      callbackBody:
        "filename=${object}&size=${size}&mimeType=${mimeType}&height=${imageInfo.height}&width=${imageInfo.width}",
      callbackBodyType: "application/x-www-form-urlencoded",
    };

    return {
      expire: dayjs().add(1, "days").unix().toString(),
      policy: formData.policy,
      signature: formData.Signature,
      accessId: formData.OSSAccessKeyId,
      host,
      dir: this.staticConfig.dir,
      callback: Buffer.from(JSON.stringify(callback)).toString("base64"),
    };
  }

  async generateSignedUrl(key: string): Promise<string> {
    const expire = Math.floor(Date.now() / 1000) + 3600; // 有效期为1小时

    // 阿里云 OSS
    if (this.ossType === "aliyun") {
      const downloadUrl = this.aliClient.signatureUrl(key, {
        expires: expire,
      });
      return downloadUrl;
    }

    // MinIO
    if (this.ossType === "minio" && this.minioClient && this.minioBucket) {
      const url = await this.minioClient.presignedGetObject(this.minioBucket, key, 3600);
      return url;
    }

    // local 或未配置
    throw new Error("generateSignedUrl is not supported for current OSS type");
  }

  async getFileAsBlob(key: string): Promise<Buffer> {
    try {
      // 阿里云 OSS
      if (this.ossType === "aliyun") {
        const result = await this.aliClient.get(key);
        const buffer = Buffer.from(result.content, "base64");
        return buffer;
      }

      // MinIO
      if (this.ossType === "minio" && this.minioClient && this.minioBucket) {
        const stream = await this.minioClient.getObject(this.minioBucket, key);
        const chunks: Buffer[] = [];
        for await (const chunk of stream) {
          chunks.push(Buffer.from(chunk));
        }
        return Buffer.concat(chunks);
      }

      throw new Error("getFileAsBlob is not supported for current OSS type");
    } catch (error) {
      throw new Error(`Error getting file: ${error.message}`);
    }
  }

  async getResult(xOssPubKeyUrl: string, file: any) {
    // 通过 Base64 解码公钥地址
    const pubKeyAddr = Buffer.from(xOssPubKeyUrl, "base64").toString("ascii");

    //  判断请求头中的 x-oss-pub-key-url 是否来源于OSS服务器
    if (!pubKeyAddr.startsWith("https://gosspublic.alicdn.com/")) {
      // 如果不是来源于OSS服务器，则返回 “verify not ok”，表明回调失败
      return {
        status: "verify not ok",
      };
    }
    // 如果 x-oss-pub-key-url 来源于OSS服务器，则返回“Ok”和文件信息，表明回调成功
    return {
      status: "Ok",
      file,
    };
  }

  async uploadFile(file: any): Promise<{ name: string; url: string }> {
    const originalName: string = file?.originalname || file?.originalName || "file";
    const ext = path.extname(originalName);
    const dateFolder = dayjs().format("YYYYMMDD");
    const objectName = `${dateFolder}/${uuidv4()}${ext}`;

    const getFileContent = async () => {
      if (file?.buffer) {
        return file.buffer as Buffer;
      }
      if (file?.path) {
        return (await fs.promises.readFile(file.path)) as Buffer;
      }
      return null;
    };

    // aliyun
    if (this.ossType === "aliyun") {
      const content = (await getFileContent()) ?? file;
      const result = await this.aliClient.put(objectName, content);
      const endpoint = this.ossConf.aliyun.endpoint;
      const bucket = this.ossConf.aliyun.bucketName;
      const url = result?.url || `https://${bucket}.${endpoint}/${objectName}`;
      return { name: originalName, url };
    }

    // minio
    if (this.ossType === "minio" && this.minioClient && this.minioBucket) {
      const content = await getFileContent();
      if (!content) {
        throw new Error("file buffer is empty");
      }

      await this.minioClient.putObject(this.minioBucket, objectName, content, content.length, {
        "Content-Type": file?.mimetype || "application/octet-stream",
      });

      const customDomain = (this.ossConf.minio.customDomain || "").trim();
      if (customDomain) {
        const base = customDomain.replace(/\/+$/, "");
        return {
          name: originalName,
          url: `${base}/${this.minioBucket}/${objectName}`,
        };
      }

      const presigned = await this.minioClient.presignedGetObject(
        this.minioBucket,
        objectName,
        24 * 60 * 60
      );
      const cleanUrl = presigned.includes("?")
        ? presigned.substring(0, presigned.indexOf("?"))
        : presigned;
      return { name: originalName, url: cleanUrl };
    }

    // local
    const storageRoot = this.ossConf.local.storagePath;
    const fullPath = path.join(storageRoot, objectName);
    await fs.promises.mkdir(path.dirname(fullPath), { recursive: true });
    const content = await getFileContent();
    if (!content) {
      throw new Error("file buffer is empty");
    }
    await fs.promises.writeFile(fullPath, content);
    return { name: originalName, url: `/${objectName}` };
  }

  async deleteFile(filePath?: string): Promise<boolean> {
    if (!filePath) return false;

    // aliyun
    if (this.ossType === "aliyun") {
      const endpoint = this.ossConf.aliyun.endpoint;
      const bucket = this.ossConf.aliyun.bucketName;
      const host = `https://${bucket}.${endpoint}`;

      const key = filePath.startsWith(host)
        ? filePath.substring(host.length + 1)
        : filePath.startsWith("http")
          ? new URL(filePath).pathname.replace(/^\/+/, "")
          : filePath.replace(/^\/+/, "");

      await this.aliClient.delete(key);
      return true;
    }

    // local
    try {
      const storageRoot = this.ossConf.local.storagePath;
      const rel = filePath.startsWith("/") ? filePath.substring(1) : filePath;
      const fullPath = path.isAbsolute(filePath) ? filePath : path.join(storageRoot, rel);
      await fs.promises.unlink(fullPath);
      return true;
    } catch {
      return false;
    }
  }

  async OCR(url: string, type: string) {
    const recognizeIdcardRequest = new $ocr_api20210707.RecognizeAllTextRequest({
      url,
      type,
    });
    const runtime = new $Util.RuntimeOptions({});
    try {
      if (!this.OCRClient) {
        return {
          data: JSON.stringify({
            code: 400,
            message: "OCR is only supported when OSS_TYPE=aliyun",
          }),
        };
      }

      const res = await this.OCRClient.recognizeAllTextWithOptions(recognizeIdcardRequest, runtime);

      return res?.body?.data;
    } catch (error) {
      Util.assertAsString(error.message);
      if (error.message.indexOf("illegalImageContent") !== -1) {
        return {
          data: JSON.stringify({
            code: 400,
            message: "非法图像内容,请上传正确图片",
          }),
        };
      }
    }
  }
}

import { Injectable, OnModuleDestroy } from "@nestjs/common";
import { OnlineUserDto } from "../auth/interfaces/user-session.interface";

interface SessionInfo {
  username: string;
  connectTime: number;
}

@Injectable()
export class SseSessionRegistry implements OnModuleDestroy {
  private readonly userEmittersMap: Map<string, Set<any>> = new Map();
  private readonly emitterUserMap: Map<any, SessionInfo> = new Map();

  userConnected(username: string, emitter: any): void {
    if (!this.userEmittersMap.has(username)) {
      this.userEmittersMap.set(username, new Set());
    }
    this.userEmittersMap.get(username)!.add(emitter);
    this.emitterUserMap.set(emitter, {
      username,
      connectTime: Date.now(),
    });
  }

  userDisconnected(username: string): void {
    const emitters = this.userEmittersMap.get(username);
    if (emitters) {
      emitters.forEach((emitter) => {
        this.emitterUserMap.delete(emitter);
      });
    }
    this.userEmittersMap.delete(username);
  }

  removeEmitter(emitter: any): void {
    const sessionInfo = this.emitterUserMap.get(emitter);
    if (!sessionInfo) {
      return;
    }

    this.emitterUserMap.delete(emitter);
    const emitters = this.userEmittersMap.get(sessionInfo.username);
    if (emitters) {
      emitters.delete(emitter);
      if (emitters.size === 0) {
        this.userEmittersMap.delete(sessionInfo.username);
      }
    }
  }

  getOnlineUserCount(): number {
    return this.userEmittersMap.size;
  }

  getTotalConnectionCount(): number {
    return this.emitterUserMap.size;
  }

  isUserOnline(username: string): boolean {
    const emitters = this.userEmittersMap.get(username);
    return emitters !== undefined && emitters.size > 0;
  }

  getOnlineUsers(): OnlineUserDto[] {
    const result: OnlineUserDto[] = [];
    this.userEmittersMap.forEach((emitters, username) => {
      let earliestLoginTime = Infinity;
      emitters.forEach((emitter) => {
        const sessionInfo = this.emitterUserMap.get(emitter);
        if (sessionInfo && sessionInfo.connectTime < earliestLoginTime) {
          earliestLoginTime = sessionInfo.connectTime;
        }
      });

      result.push({
        username,
        sessionCount: emitters.size,
        loginTime: earliestLoginTime === Infinity ? Date.now() : earliestLoginTime,
      });
    });
    return result;
  }

  getAllEmitters(): Set<any> {
    return new Set(this.emitterUserMap.keys());
  }

  getUserEmitters(username: string): Set<any> | undefined {
    return this.userEmittersMap.get(username);
  }

  onModuleDestroy() {
    // 主动关闭所有 SSE 连接的 HTTP 响应
    this.emitterUserMap.forEach((sessionInfo, emitter) => {
      try {
        if (emitter.complete) {
          emitter.complete();
        }
      } catch (_e) {}
    });
    this.userEmittersMap.clear();
    this.emitterUserMap.clear();
  }
}

import { Controller, Get, Req, Res, Query } from "@nestjs/common";
import { ApiTags, ApiOperation, ApiBearerAuth } from "@nestjs/swagger";
import { Request, Response } from "express";
import { SseService } from "./sse.service";
import { JwtService } from "@nestjs/jwt";
import { ConfigService } from "@nestjs/config";
import { Public } from "../common/decorators/auth.decorator";

@ApiTags("13. SSE连接")
@ApiBearerAuth()
@Controller("sse")
export class SseController {
  constructor(
    private readonly sseService: SseService,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService
  ) {}

  @Public()
  @Get("connect")
  @ApiOperation({ summary: "建立SSE连接" })
  async connect(@Req() req: Request, @Res() res: Response) {
    const authHeader = req.headers.authorization;

    if (!authHeader?.startsWith("Bearer ")) {
      res.status(401).json({ code: 401, msg: "Unauthorized" });
      return;
    }

    const jwtToken = authHeader.slice(7);

    try {
      const secret = this.configService.getOrThrow<string>("jwt.secretKey");
      const payload = await this.jwtService.verifyAsync(jwtToken, { secret });
      const username = payload.username;

      if (!username) {
        res.status(401).json({ code: 401, msg: "Invalid token" });
        return;
      }

      res.setHeader("Content-Type", "text/event-stream");
      res.setHeader("Cache-Control", "no-cache");
      res.setHeader("Connection", "keep-alive");
      res.setHeader("X-Accel-Buffering", "no");

      const sendEvent = (eventName: string, data: any) => {
        res.write(`event: ${eventName}\n`);
        res.write(`data: ${JSON.stringify(data)}\n\n`);
      };

      const emitter = {
        send: sendEvent,
        complete: () => {
          try {
            res.end();
          } catch (_e) {}
        },
      };

      const registry = (this.sseService as any).sessionRegistry;
      registry.userConnected(username, emitter);

      sendEvent("online-count", registry.getOnlineUserCount());

      const heartbeatInterval = setInterval(() => {
        try {
          res.write(": heartbeat\n\n");
        } catch (_e) {
          clearInterval(heartbeatInterval);
        }
      }, 30000);

      req.on("close", () => {
        clearInterval(heartbeatInterval);
        registry.removeEmitter(emitter);
        this.sseService.sendOnlineCount();
      });
    } catch (_e) {
      res.status(401).json({ code: 401, msg: "Invalid token" });
    }
  }

  @Get("online-count")
  @ApiOperation({ summary: "获取在线用户数" })
  getOnlineCount() {
    return this.sseService.getOnlineUserCount();
  }
}

