import { Injectable, Logger } from "@nestjs/common";
import { SseSessionRegistry } from "./sse-session-registry.service";
import { Observable, Subject } from "rxjs";

export const SSE_TOPICS = {
  DICT: "dict",
  ONLINE_COUNT: "online-count",
  SYSTEM: "system",
} as const;

interface DictChangeEvent {
  dictCode: string;
  timestamp: number;
}

@Injectable()
export class SseService {
  private readonly logger = new Logger(SseService.name);
  private readonly eventSubject = new Subject<{ eventName: string; data: any; username?: string }>();

  constructor(private readonly sessionRegistry: SseSessionRegistry) {}

  createConnection(username: string): Observable<MessageEvent> {
    return new Observable<MessageEvent>((subscriber) => {
      const emitter = {
        send: (eventName: string, data: any) => {
          subscriber.next({ data: JSON.stringify({ eventName, data }) } as MessageEvent);
        },
        complete: () => {
          subscriber.complete();
        },
      };

      this.sessionRegistry.userConnected(username, emitter as any);
      this.logger.debug(`SSE connection established: username=${username}`);

      // 发送初始在线人数
      this.sendOnlineCount();

      return () => {
        this.sessionRegistry.removeEmitter(emitter as any);
        this.logger.debug(`SSE connection closed: username=${username}`);
        this.sendOnlineCount();
      };
    });
  }

  sendDictChange(dictCode: string): void {
    const event: DictChangeEvent = {
      dictCode,
      timestamp: Date.now(),
    };
    this.broadcast(SSE_TOPICS.DICT, event);
    this.logger.debug(`Dict change event sent: dictCode=${dictCode}`);
  }

  sendOnlineCount(): void {
    const count = this.sessionRegistry.getOnlineUserCount();
    this.broadcast(SSE_TOPICS.ONLINE_COUNT, count);
  }

  sendToUser(username: string, eventName: string, data: any): void {
    const emitters = this.sessionRegistry.getUserEmitters(username);
    if (emitters) {
      emitters.forEach((emitter: any) => {
        try {
          emitter.send(eventName, data);
        } catch (e) {
          this.logger.warn(`Failed to send event to user: ${username}`);
          this.sessionRegistry.removeEmitter(emitter);
        }
      });
    }
    this.logger.debug(`Event sent to user: username=${username} event=${eventName}`);
  }

  getOnlineUsers() {
    return this.sessionRegistry.getOnlineUsers();
  }

  getOnlineUserCount(): number {
    return this.sessionRegistry.getOnlineUserCount();
  }

  sendSystemMessage(message: string): void {
    const systemMessage = {
      sender: "系统通知",
      content: message,
      timestamp: Date.now(),
    };
    this.broadcast(SSE_TOPICS.SYSTEM, systemMessage);
    this.logger.debug(`System message sent: ${message}`);
  }

  private broadcast(eventName: string, data: any): void {
    const emitters = this.sessionRegistry.getAllEmitters();
    emitters.forEach((emitter: any) => {
      try {
        emitter.send(eventName, data);
      } catch (e) {
        this.sessionRegistry.removeEmitter(emitter);
      }
    });
  }
}

import {
  Controller,
  Get,
  Post,
  Body,
  Put,
  Param,
  Delete,
  Query,
  HttpException,
  HttpStatus,
  SetMetadata,
} from "@nestjs/common";
import { DeptService } from "./dept.service";
import { CreateDeptDto } from "./dto/create-dept.dto";
import { UpdateDeptDto } from "./dto/update-dept.dto";
import { ApiOperation, ApiTags } from "@nestjs/swagger";
import { CurrentUser } from "../../common/decorators/current-user.decorator";
import { Permissions } from "../../common/decorators/auth.decorator";
import { Log } from "../../common/decorators/log.decorator";
import { ActionTypeValue } from "../../common/enums/action-type.enum";
import { LogModuleValue } from "../../common/enums/log-module.enum";
import { DataPermission } from "../../common/decorators/data-permission.decorator";

/**
 * 部门接口控制器
 */
@ApiTags("05.部门接口")
@Controller("depts")
export class DeptController {
  private readonly deptService: DeptService;

  constructor(deptService: DeptService) {
    this.deptService = deptService;
  }

  @ApiOperation({ summary: "部门下拉列表" })
  @Get("options")
  @SetMetadata("resource", "sys_dept")
  async getOptions() {
    return await this.deptService.findAllOptions();
  }

  @ApiOperation({ summary: "获取部门表格树形列表" })
  @Get()
  @SetMetadata("resource", "sys_dept")
  @DataPermission({
    // Prisma 形态（生效中）
    model: "SysDept",
    deptField: "id",
    ownerField: "createBy",
    // TypeORM 遗留形态（摘除 TypeORM 后删除）
    deptAlias: "dept",
    deptIdColumnName: "id",
    userAlias: "dept",
    userIdColumnName: "create_by",
  })
  async findAll(@Query("keywords") keywords?: string, @Query("status") status?: string) {
    return await this.deptService.findAll(keywords, status);
  }

  @ApiOperation({ summary: "创建部门" })
  @Post()
  @Permissions("sys:dept:create")
  async create(@CurrentUser("userId") currentUserId: string, @Body() createDeptDto: CreateDeptDto) {
    return await this.deptService.create({
      ...createDeptDto,
      createBy: currentUserId,
    });
  }

  @ApiOperation({ summary: "获取部门详情" })
  @Get(":id/form")
  async getDeptForm(@Param("id") id: string) {
    const dept = await this.deptService.getDeptForm(id);
    if (!dept) {
      throw new HttpException("部门不存在", HttpStatus.NOT_FOUND);
    }
    return dept;
  }

  @ApiOperation({ summary: "编辑部门" })
  @Log(LogModuleValue.DEPT, ActionTypeValue.UPDATE)
  @Put(":id")
  @Permissions("sys:dept:update")
  async update(
    @CurrentUser("userId") currentUserId: string,
    @Param("id") id: string,
    @Body() requestBody: any
  ) {
    const updateDeptDto: UpdateDeptDto = {
      name: requestBody.name,
      code: requestBody.code,
      parentId:
        requestBody.parentId === undefined ||
        requestBody.parentId === null ||
        requestBody.parentId === ""
          ? undefined
          : String(requestBody.parentId),
      sort: Number(requestBody.sort),
      status: Number(requestBody.status),
    };

    const result = await this.deptService.updateDept(id, {
      ...updateDeptDto,
      updateBy: currentUserId,
    });

    if (!result) {
      throw new HttpException("部门不存在", HttpStatus.NOT_FOUND);
    }
    return result;
  }

  @ApiOperation({ summary: "删除部门" })
  @Log(LogModuleValue.DEPT, ActionTypeValue.DELETE)
  @Delete(":ids")
  @Permissions("sys:dept:delete")
  async deleteDepartments(@Param("ids") ids: string) {
    const idArray = ids
      .split(",")
      .map((id) => id.trim())
      .filter(Boolean);

    for (const id of idArray) {
      const success = await this.deptService.deleteDept(id);
      if (!success) {
        throw new HttpException(`删除部门失败，ID: ${id}`, HttpStatus.BAD_REQUEST);
      }
    }
    return { message: "部门删除成功" };
  }
}

import { IsOptional, IsEnum, IsDateString, IsInt, Min } from "class-validator";

export enum ActionTypeEnum {
  LOGIN = "LOGIN",
  LOGOUT = "LOGOUT",
  CHANGE_PWD = "CHANGE_PWD",
  UPDATE_PROFILE = "UPDATE_PROFILE",
  API = "API",
}

﻿import { Injectable } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import { PrismaService } from "../../common/prisma/prisma.service";
import { toBigInt } from "../../common/prisma/prisma-ids";
import {
  endOfDay,
  enumerateDays,
  formatDateTimeInZone,
  getAppTimeZone,
  startOfDay,
  toDayString,
} from "../../common/utils/date.util";
import { LogQueryDto } from "./dto/log-query.dto";
import { LogPageDto } from "./dto/log-page.dto";
import { VisitTrendDto } from "./dto/visit-trend.dto";
import { VisitStatsDto } from "./dto/visit-stats.dto";
import { ActionTypeEnum, ActionTypeValue } from "../../common/enums/action-type.enum";
import { LogModuleEnum, LogModuleValue } from "../../common/enums/log-module.enum";
import { parseUserAgent } from "../../common/utils/user-agent.util";
import { LOG_COLUMN_LIMITS, clampLogText, resolveLogTitle } from "./log.util";

export interface ManualLogParams {
  /** 所属模块（原实现漏传，导致 module/title 为 NOT NULL 的插入依赖 MySQL 非严格模式，此处显式必填） */
  module: LogModuleValue;
  actionType: ActionTypeValue;
  /** 不传则按「模块label-操作label」自动生成 */
  title?: string;
  content?: string;
  operatorId: string | null;
  operatorName?: string;
  requestMethod: string;
  requestUri: string;
  ip?: string;
  userAgent?: string;
  status?: number;
  errorMsg?: string;
  executionTime?: number;
}

/**
 * `sortBy` 允许的字段：沿用历史入参的**下划线列名**，映射到 Prisma 字段名。
 * 使用白名单而非直接透传，避免排序字段被拼进 SQL。
 */
const SORT_FIELD_MAP: Record<string, keyof Prisma.SysLogOrderByWithRelationInput> = {
  create_time: "createTime",
  execution_time: "executionTime",
  action_type: "actionType",
  request_uri: "requestUri",
  request_method: "requestMethod",
  ip: "ip",
  status: "status",
};

/** 关键字检索覆盖的列（用户可见文本 + 请求信息 + 客户端信息） */
const KEYWORD_FIELDS = [
  "title",
  "content",
  "requestUri",
  "requestMethod",
  "province",
  "city",
  "browser",
  "os",
  "device",
  "errorMsg",
] as const;

/**
 * 日志服务
 */
@Injectable()
export class LogService {
  constructor(private readonly prisma: PrismaService) {}

  async getLogPage(query: LogQueryDto) {
    const { pageNum, pageSize, keywords, createTime, sortBy, order } = query;

    const pageNumSafe = Number(pageNum) > 0 ? Number(pageNum) : 1;
    const pageSizeSafe = Number(pageSize) > 0 ? Number(pageSize) : 20;

    const where: Prisma.SysLogWhereInput = {};
    const and: Prisma.SysLogWhereInput[] = [];

    if (keywords) {
      // MySQL 默认排序规则不区分大小写，PostgreSQL 的 LIKE 区分；
      // 用 insensitive 保持「搜 admin 能命中 Admin」的既有体验。
      and.push({
        OR: KEYWORD_FIELDS.map((field) => ({
          [field]: { contains: keywords, mode: "insensitive" as const },
        })),
      });
    }

    // 时间区间按**应用时区**的自然日解释，避免依赖进程时区
    const timeZone = getAppTimeZone();
    const startTime = createTime?.[0];
    const endTime = createTime?.[1];
    if (startTime) {
      const from = startOfDay(startTime, timeZone);
      if (from) and.push({ createTime: { gte: from } });
    }
    if (endTime) {
      const to = endOfDay(endTime, timeZone);
      if (to) and.push({ createTime: { lte: to } });
    }

    if (and.length) where.AND = and;

    const direction: Prisma.SortOrder =
      (order || "").toUpperCase() === "ASC" ? "asc" : "desc";
    const sortField = sortBy ? SORT_FIELD_MAP[sortBy] : undefined;
    const orderBy: Prisma.SysLogOrderByWithRelationInput = sortField
      ? { [sortField]: direction }
      : { createTime: "desc" };

    const [records, total] = await Promise.all([
      this.prisma.scoped.sysLog.findMany({
        where,
        orderBy,
        skip: (pageNumSafe - 1) * pageSizeSafe,
        take: pageSizeSafe,
      }),
      this.prisma.scoped.sysLog.count({ where }),
    ]);

    const list: LogPageDto[] = records.map((item) => ({
      id: item.id.toString(),
      module: item.module !== null ? LogModuleEnum.getLabel(item.module) : null,
      actionType: item.actionType !== null ? ActionTypeEnum.getLabel(item.actionType) : null,
      title: item.title,
      content: item.content,
      operatorId: item.operatorId !== null ? item.operatorId.toString() : null,
      operatorName: item.operatorName,
      status: item.status,
      requestUri: item.requestUri,
      requestMethod: item.requestMethod,
      ip: item.ip,
      region: [item.province, item.city].filter(Boolean).join(" ") || null,
      device: item.device,
      browser: item.browser,
      os: item.os,
      executionTime: item.executionTime,
      errorMsg: item.errorMsg,
      createTime: formatDateTimeInZone(item.createTime, timeZone),
    }));

    return {
      data: list,
      page: {
        pageNum: pageNumSafe,
        pageSize: pageSizeSafe,
        total,
      },
    };
  }

  async getVisitTrend(startDate: string, endDate: string): Promise<VisitTrendDto> {
    const timeZone = getAppTimeZone();
    const start = startOfDay(startDate, timeZone);
    const end = endOfDay(endDate, timeZone);
    if (!start || !end) {
      return { dates: [], pvList: [], uvList: [] };
    }

    const firstDay = toDayString(start, timeZone);
    const lastDay = toDayString(end, timeZone);
    if (!firstDay || !lastDay) {
      return { dates: [], pvList: [], uvList: [] };
    }
    const dates = enumerateDays(firstDay, lastDay);
    if (!dates.length) {
      return { dates: [], pvList: [], uvList: [] };
    }

    // 按天分组必须显式指定时区：timestamptz 直接 to_char 会按 UTC 日界切分，
    // 北京时间 07:00 的数据会被归到前一天（见 scripts/verify-datetime-semantics.mjs 契约 4）。
    const [pvRows, uvRows] = await Promise.all([
      this.prisma.$queryRaw<Array<{ day: string; count: number }>>`
        SELECT to_char(create_time AT TIME ZONE (${timeZone}::text), 'YYYY-MM-DD') AS day,
               COUNT(*)::int AS count
        FROM sys_log
        WHERE create_time >= ${start} AND create_time <= ${end}
        GROUP BY 1
      `,
      this.prisma.$queryRaw<Array<{ day: string; count: number }>>`
        SELECT to_char(create_time AT TIME ZONE (${timeZone}::text), 'YYYY-MM-DD') AS day,
               COUNT(DISTINCT ip)::int AS count
        FROM sys_log
        WHERE create_time >= ${start} AND create_time <= ${end}
        GROUP BY 1
      `,
    ]);

    const pvMap = new Map<string, number>();
    for (const row of pvRows) pvMap.set(row.day, Number(row.count) || 0);

    const uvMap = new Map<string, number>();
    for (const row of uvRows) uvMap.set(row.day, Number(row.count) || 0);

    return {
      dates,
      pvList: dates.map((d) => pvMap.get(d) ?? 0),
      uvList: dates.map((d) => uvMap.get(d) ?? 0),
    };
  }

  async getVisitStats(): Promise<VisitStatsDto> {
    const timeZone = getAppTimeZone();
    const now = new Date();
    const todayStart = startOfDay(now, timeZone);
    const todayEnd = endOfDay(now, timeZone);

    // UV 统计：按 IP 粗略统计（COUNT(DISTINCT) 会忽略 NULL，与旧实现一致）
    const uvSql = (withToday: boolean) =>
      withToday
        ? this.prisma.$queryRaw<Array<{ count: number }>>`
            SELECT COUNT(DISTINCT ip)::int AS count FROM sys_log
            WHERE create_time >= ${todayStart} AND create_time <= ${todayEnd}
          `
        : this.prisma.$queryRaw<Array<{ count: number }>>`
            SELECT COUNT(DISTINCT ip)::int AS count FROM sys_log
          `;

    const [todayUvRows, totalUvRows, todayPvCount, totalPvCount] = await Promise.all([
      uvSql(true),
      uvSql(false),
      this.prisma.sysLog.count({
        where: { createTime: { gte: todayStart ?? undefined, lte: todayEnd ?? undefined } },
      }),
      this.prisma.sysLog.count(),
    ]);

    const todayUvCount = Number(todayUvRows[0]?.count ?? 0);
    const totalUvCount = Number(totalUvRows[0]?.count ?? 0);

    const prevUvTotal = totalUvCount - todayUvCount;
    const prevPvTotal = totalPvCount - todayPvCount;

    const uvGrowthRate =
      prevUvTotal > 0 ? Number(((todayUvCount / prevUvTotal - 1) * 100).toFixed(2)) : null;
    const pvGrowthRate =
      prevPvTotal > 0 ? Number(((todayPvCount / prevPvTotal - 1) * 100).toFixed(2)) : null;

    return {
      todayUvCount,
      totalUvCount,
      uvGrowthRate,
      todayPvCount,
      totalPvCount,
      pvGrowthRate,
    };
  }

  /**
   * 手动记录日志（用于登录/登出等 Public 接口）
   * 拦截器无法从安全上下文获取 userId，需在业务逻辑中手动传入
   */
  async saveManualLog(params: ManualLogParams) {
    const { browser, os } = parseUserAgent(params.userAgent ?? "");

    await this.prisma.sysLog.create({
      data: {
        module: params.module,
        actionType: params.actionType,
        title: clampLogText(
          resolveLogTitle(params.module, params.actionType, params.title),
          LOG_COLUMN_LIMITS.title
        ) as string,
        content: params.content ?? null,
        requestMethod: clampLogText(params.requestMethod, LOG_COLUMN_LIMITS.requestMethod),
        requestUri: clampLogText(params.requestUri, LOG_COLUMN_LIMITS.requestUri),
        ip: clampLogText(params.ip, LOG_COLUMN_LIMITS.ip),
        province: null,
        city: null,
        device: clampLogText(os, LOG_COLUMN_LIMITS.device),
        os: clampLogText(os, LOG_COLUMN_LIMITS.os),
        browser: clampLogText(browser, LOG_COLUMN_LIMITS.browser),
        status: params.status ?? 1,
        errorMsg: clampLogText(params.errorMsg, LOG_COLUMN_LIMITS.errorMsg),
        executionTime: params.executionTime ?? 0,
        operatorId: toBigInt(params.operatorId),
        operatorName: clampLogText(params.operatorName, LOG_COLUMN_LIMITS.operatorName),
        createTime: new Date(),
      },
    });
  }
}

import { ActionTypeEnum, type ActionTypeValue } from "../../common/enums/action-type.enum";
import { LogModuleEnum, type LogModuleValue } from "../../common/enums/log-module.enum";

/**
 * `sys_log` 各字符列的物理上限（与 `prisma/schema.prisma` 保持一致）。
 * PostgreSQL 对 `varchar(n)` 是**严格**校验（超出直接报错，不像旧 MySQL 非严格模式
 * 会静默截断），而日志写入在调用侧普遍 `catch` 吞掉异常，一旦超长就会「日志静默丢失」。
 * 因此写入前统一截断：宁可少几个字符，也不要丢掉整条记录。
 */
export const LOG_COLUMN_LIMITS = {
  title: 100,
  operatorName: 50,
  requestUri: 255,
  requestMethod: 10,
  ip: 45,
  province: 100,
  city: 100,
  device: 100,
  os: 100,
  browser: 100,
  errorMsg: 255,
} as const;

/** 按上限截断，空值保持空值 */
export function clampLogText(
  value: string | null | undefined,
  limit: number
): string | null {
  if (value === null || value === undefined) return null;
  const text = String(value);
  return text.length > limit ? text.slice(0, limit) : text;
}

/**
 * 统一日志标题口径：显式给定优先，否则拼成「模块label-操作label」。
 * 拦截器与手动写入两条路径共用，避免同一类日志出现两种标题。
 */
export function resolveLogTitle(
  module: LogModuleValue,
  actionType: ActionTypeValue,
  title?: string | null
): string {
  const explicit = title?.trim();
  if (explicit) return explicit;
  return `${LogModuleEnum.getLabel(module)}-${ActionTypeEnum.getLabel(actionType)}`;
}

﻿import { CallHandler, ExecutionContext, Injectable, NestInterceptor } from "@nestjs/common";
import { Reflector } from "@nestjs/core";
import { Observable, throwError } from "rxjs";
import { catchError, tap } from "rxjs/operators";
import { PrismaService } from "../../common/prisma/prisma.service";
import { toBigInt } from "../../common/prisma/prisma-ids";
import { LOG_MODULE, LogMetadata } from "../../common/decorators/log.decorator";
import { parseUserAgent } from "../../common/utils/user-agent.util";
import { LOG_COLUMN_LIMITS, clampLogText, resolveLogTitle } from "./log.util";

@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  constructor(
    private readonly prisma: PrismaService,
    private readonly reflector: Reflector
  ) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    if (context.getType() !== "http") {
      return next.handle();
    }

    const now = Date.now();
    const http = context.switchToHttp();
    const req: any = http.getRequest();

    return next.handle().pipe(
      tap(async () => {
        await this.saveLog(context, req, now, null);
      }),
      catchError((err) => {
        this.saveLog(context, req, now, err).catch(() => {});
        return throwError(() => err);
      })
    );
  }

  private async saveLog(context: ExecutionContext, req: any, startTime: number, error: any) {
    try {
      const duration = Date.now() - startTime;
      const userAgent = (req.headers?.["user-agent"] as string) || "";
      const { browser, os } = parseUserAgent(userAgent);

      // 没有 @Log 装饰器的接口不记录日志
      const logMetadata = this.reflector.get<LogMetadata>(LOG_MODULE, context.getHandler());
      if (!logMetadata) return;

      const { module, actionType, title, content } = logMetadata;

      const xff = (req.headers?.["x-forwarded-for"] as string) || "";
      const realIp = xff.split(",")[0].trim();

      await this.prisma.sysLog.create({
        data: {
          module,
          actionType,
          title: clampLogText(
            resolveLogTitle(module, actionType, title),
            LOG_COLUMN_LIMITS.title
          ) as string,
          content: content || null,
          requestMethod: clampLogText(req.method, LOG_COLUMN_LIMITS.requestMethod),
          requestUri: clampLogText(
            req.originalUrl || req.url,
            LOG_COLUMN_LIMITS.requestUri
          ),
          ip: clampLogText(
            realIp || req.ip || req.connection?.remoteAddress || null,
            LOG_COLUMN_LIMITS.ip
          ),
          province: null,
          city: null,
          device: clampLogText(os, LOG_COLUMN_LIMITS.device),
          os: clampLogText(os, LOG_COLUMN_LIMITS.os),
          browser: clampLogText(browser, LOG_COLUMN_LIMITS.browser),
          status: error ? 0 : 1,
          errorMsg: clampLogText(error?.message, LOG_COLUMN_LIMITS.errorMsg),
          executionTime: duration,
          operatorId: toBigInt(req.user?.userId),
          operatorName: clampLogText(req.user?.username, LOG_COLUMN_LIMITS.operatorName),
          createTime: new Date(),
        },
      });
    } catch {
      // 日志保存失败不影响主流程
    }
  }
}

﻿import { IsBoolean, IsIn, IsNumber, IsOptional, IsString, MaxLength } from "class-validator";
import { Transform } from "class-transformer";

/** 菜单创建参数 */
export class CreateMenuDto {
  @IsString()
  @MaxLength(20)
  name: string;

  @IsOptional()
  @IsNumber()
  sort?: number;

  @IsOptional()
  @Transform(({ value }) =>
    value === undefined || value === null || value === "" ? undefined : String(value)
  )
  @IsString()
  parentId?: string;

  /** 菜单类型: C-目录 M-菜单 B-按钮 */
  @IsString()
  @IsIn(["C", "M", "B"])
  type: string;

  @IsOptional()
  @IsString()
  @MaxLength(50)
  icon?: string;

  @IsOptional()
  @IsString()
  @MaxLength(128)
  component?: string;

  @IsOptional()
  @IsString()
  @MaxLength(255)
  routeName?: string;

  @IsOptional()
  @IsString()
  @MaxLength(128)
  routePath?: string;

  @IsOptional()
  @IsString()
  @MaxLength(128)
  redirect?: string;

  @IsOptional()
  @IsString()
  @MaxLength(50)
  permissionType?: string;

  @IsOptional()
  @IsString()
  @MaxLength(50)
  authSymbol?: string;

  /** 按钮权限标识 */
  @IsOptional()
  @IsString()
  @MaxLength(128)
  perm?: string;

  @IsOptional()
  @IsNumber()
  orderWeight?: number;

  /** 目录只有一个子路由时是否始终显示 */
  @IsOptional()
  @IsNumber()
  alwaysShow?: number;

  /** 是否缓存页面 */
  @IsOptional()
  @IsNumber()
  keepAlive?: number;

  /** 是否隐藏菜单 */
  @IsOptional()
  @IsNumber()
  visible?: number;

  @IsOptional()
  @IsString()
  remark?: string;

  /** 是否新标签页打开 */
  @IsOptional()
  @IsBoolean()
  createTab?: boolean;

  /** 路由参数 */
  @IsOptional()
  params?: Record<string, any>;
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Patch,
  Post,
  Put,
  Query,
  SetMetadata,
} from "@nestjs/common";
import { ApiOperation, ApiTags } from "@nestjs/swagger";
import { CurrentUser } from "../../common/decorators/current-user.decorator";
import { Permissions } from "../../common/decorators/auth.decorator";
import { Log } from "../../common/decorators/log.decorator";
import { ActionTypeValue } from "../../common/enums/action-type.enum";
import { LogModuleValue } from "../../common/enums/log-module.enum";
import { MenuService } from "./menu.service";
import { CreateMenuDto } from "./dto/create-menu.dto";
import { UpdateMenuDto } from "./dto/update-menu.dto";

@ApiTags("04.菜单接口")
@Controller("menus")
export class MenuController {
  constructor(private readonly menuService: MenuService) {}

  @ApiOperation({ summary: "获取路由列表" })
  @Get("routes")
  async getRoutes(@CurrentUser("userId") userId: string) {
    return await this.menuService.getRoutes(userId);
  }

  @ApiOperation({ summary: "菜单下拉树形列表" })
  @Get("options")
  async getMenuOptions() {
    return await this.menuService.findOptions();
  }

  @ApiOperation({ summary: "获取菜单列表" })
  @Get()
  @SetMetadata("resource", "sys_menu")
  async getMenus(@Query("keywords") keywords: string) {
    return await this.menuService.getMenus(keywords);
  }

  @ApiOperation({ summary: "新增菜单" })
  @Post()
  @Permissions("sys:menu:create")
  async create(@CurrentUser("userId") currentUserId: string, @Body() createMenuDto: CreateMenuDto) {
    return await this.menuService.create({
      ...createMenuDto,
    });
  }

  @ApiOperation({ summary: "获取菜单表单数据" })
  @Get(":id/form")
  @Permissions("sys:menu:update")
  async getMenuForm(@Param("id") id: string): Promise<any> {
    return await this.menuService.getMenuForm(id);
  }

  @ApiOperation({ summary: "修改菜单" })
  @Put(":id")
  @Permissions("sys:menu:update")
  updateMenu(@Param("id") id: string, @Body() updateMenuDto: UpdateMenuDto): any {
    return this.menuService.update(id, updateMenuDto);
  }

  @ApiOperation({ summary: "修改菜单显示状态" })
  @Log(LogModuleValue.MENU, ActionTypeValue.UPDATE)
  @Patch(":id")
  @Permissions("sys:menu:update")
  async update(@Param("id") id: string, @Query("visible") visible: number) {
    return await this.menuService.update(id, {
      visible: visible,
    } as any);
  }

  @ApiOperation({ summary: "删除菜单" })
  @Log(LogModuleValue.MENU, ActionTypeValue.DELETE)
  @Delete(":id")
  @Permissions("sys:menu:delete")
  deleteMenu(@Param("id") id: string) {
    return this.menuService.deleteMenu(id);
  }
}

﻿import { forwardRef, Inject, Injectable } from "@nestjs/common";
import { Prisma, SysMenu as SysMenuModel } from "@prisma/client";
import { PrismaService } from "../../common/prisma/prisma.service";
import { toBigInt, toBigIntArray } from "../../common/prisma/prisma-ids";
import { BusinessException } from "../../common/exceptions/business.exception";
import { CreateMenuDto } from "./dto/create-menu.dto";
import { UpdateMenuDto } from "./dto/update-menu.dto";
import { UserService } from "../user/user.service";
import { RolePermService } from "../role/role-permission.service";
import { Route } from "./interfaces/menu.interface";

/**
 * 菜单对外视图。
 *
 * 主键与父节点 ID 一律转成**字符串**：原 TypeORM 配置 `bigNumberStrings: true`，
 * 主键本就以字符串出入，前端（`MenuItem.id` / `parentId` / `OptionItem.value`）全程按 string 处理。
 * 且本模块的两个方法仍被未迁移的模块消费：
 *  · `getRoutes()` ← `MenuController`（只做转发）
 *  · `MenuService` 自身被 `AuthModule`/`UserModule` 间接依赖的 `MenuModule` 导出
 * ⇒ 字符串主键契约不能变。
 *
 * `type` 字段在 schema 里的列名是 `type`（Prisma 属性名为 `menuType`，靠 `@map` 映射），
 * 对外仍叫 `type` —— 前端 `MenuItem.type`、`buildRoutes` 的过滤条件都按这个名字。
 */
export interface MenuView {
  id: string;
  parentId: string;
  treePath: string | null;
  name: string;
  type: string;
  routeName: string | null;
  routePath: string | null;
  component: string | null;
  perm: string | null;
  alwaysShow: number | null;
  keepAlive: number | null;
  visible: number;
  sort: number;
  icon: string | null;
  redirect: string | null;
  params: unknown;
  createTime: Date | null;
  updateTime: Date | null;
}

function toMenuView(menu: SysMenuModel): MenuView {
  return {
    id: menu.id.toString(),
    parentId: menu.parentId.toString(),
    treePath: menu.treePath,
    name: menu.name,
    type: menu.menuType,
    routeName: menu.routeName,
    routePath: menu.routePath,
    component: menu.component,
    perm: menu.perm,
    alwaysShow: menu.alwaysShow,
    keepAlive: menu.keepAlive,
    visible: menu.visible,
    sort: menu.sort,
    icon: menu.icon,
    redirect: menu.redirect,
    params: menu.params,
    createTime: menu.createTime,
    updateTime: menu.updateTime,
  };
}

/** 顶层判定：空、`"0"` 都算根（与 `buildMenuTree` / `buildOptionsTree` 的原逻辑一致） */
function isRootMenu(view: { parentId: string }): boolean {
  return !view.parentId || view.parentId === "0";
}

/**
 * 菜单服务（Prisma 版）
 *
 * 数据访问客户端：菜单是**权限元数据**，原 `DataPermissionPlugin` 也从不作用于 `sys_menu`
 * （该插件只覆盖带 `is_deleted` + 数据范围的业务表），因此全程走**基础客户端**
 * （`this.prisma.sysMenu`），不用 `this.prisma.scoped`。与 `role` 模块口径一致。
 *
 * `sys_menu` 的两点结构特性（决定了本模块的写法）：
 *  · **没有 `is_deleted`** —— 「菜单属于系统元数据，不需要审计字段和逻辑删除」，
 *    所以本模块的查询一律**不带逻辑删除过滤**，删除是**物理删除**；
 *  · **没有 `create_by` / `update_by`** —— 只有 `create_time` / `update_time`，
 *    因此不能套 `auditOnCreate()` / `auditOnUpdate()`（它们会写 `createBy`/`updateBy`，
 *    对 `SysMenu` 而言那两个键不是列 ⇒ 编译期就会报错），改为显式写时间列。
 *
 * 🔴 本次移植**修掉的两处写路径缺陷**（均已在 `scripts/verify-menu-module.ts` 固化为回归断言）：
 *
 *  1. **请求体不带 `parentId` 会把子菜单整体「上提」到根节点**。
 *     原实现无条件执行 `const newParentId = parentId || "0"`，再在
 *     `newParentId !== menu.parentId` 时重算自己的 `treePath` **并级联改写全部子孙的 `treePath`**。
 *     而 `MenuController.update()`（`PATCH /menus/:id?visible=0` 那个「显示/隐藏」开关）
 *     只传 `{ visible }` ⇒ 点一次隐藏，该菜单连同其子树会被搬到根节点，`treePath` 全被冲掉。
 *     现改为：**只有请求显式给出 `parentId` 时才动 `parentId` / `treePath`**。
 *     前端表单（`normalizeMenuPayload()` 展开 `formData`，其 `parentId` 恒有值）
 *     始终携带 `parentId`，故接口契约不变。
 *
 *  2. **请求体带上表里不存在的字段会让 `PUT /menus/:id` 直接 500**。
 *     `CreateMenuDto` 里有 5 个字段在 `sys_menu` 中**没有对应列**：
 *     `permissionType` / `authSymbol` / `orderWeight` / `remark` / `createTab`（模板遗留）。
 *     原实现把整个 DTO 丢给 `repository.update()`，而 TypeORM 的
 *     `UpdateQueryBuilder#createUpdateExpression()` 会对**每一个**传入键调用
 *     `metadata.findColumnsWithPropertyPath()`，查不到就
 *     `throw new EntityPropertyNotFoundError`（`QueryBuilder#createPropertyPath()` 只按
 *     `Object.keys()` 收集路径，不做白名单过滤；`findColumnsWithPropertyPath` 未命中时返回 `[]`，
 *     由调用方抛错）⇒ 只要请求体带上这 5 个之一就是 HTTP 500。
 *     本次移植改为**显式逐列挑选**，未知字段一律忽略 —— 这也让 update 的行为对齐到 create
 *     （`save()` 走 INSERT 时本就只按元数据取列，未知字段被静默忽略）。
 *
 * 【已知缺陷·保持原行为】不做修正、仅登记：
 *  · 删除菜单只删 `sys_menu`，**不清理 `sys_role_menu` 的孤儿关联行**。
 *    原库（`sql/mysql/niulai_admin.sql`）**零外键**（已核对：`grep -c "FOREIGN KEY"` = 0），
 *    所以这本来就是既有行为，不是移植引入的。
 *  · `params` 在「表单 → 库 → 表单」之间**不能往返**：前端提交的是
 *    `[{ key, value }]` 数组，而 `getMenuForm()` 按**普通对象**用 `Object.entries()` 解码
 *    ⇒ 数组会被解成 `[{ key: "0", value: "[object Object]" }]`。
 *    由于 `params` 会被 `buildRoutes()` 原样塞进 `route.meta.params` 交给前端路由消费，
 *    擅自改存储形状会影响路由行为，故本次**不动**，留作独立任务。
 *  · `sort` 相同的同级菜单，返回顺序由引擎决定（原 `ORDER BY sort ASC` 单键排序，
 *    两库都不保证 tie 的次序）。
 *  · `treePath` 的「是否含自身 ID」两处口径不同：`create()` 写「父路径,自身ID」（含自身），
 *    而 `update()` 只写 `generateMenuTreePath(新父)` 的返回值（**不含**自身），
 *    `updateChildrenTreePath()` 写「新父路径,父自身ID」（含父、不含子）。
 *    另外 `update()` 把菜单提为顶层时 `treePath` 落 `"0"`，而 `create()` 落**自身 ID**。
 *    影响有限 —— **祖先链始终完整**，`getMenus()` 的祖先补全不受影响；
 *    但「`treePath` 一定以自身 ID 结尾」这条不成文约定只对 `create()` 出来的子树成立。
 *  · `findButtons()` / `findPermsByMenuIds()` 的 SQL 是 `id IN (入参) AND type = 'B'`，
 *    入参必须是**按钮菜单自身的 ID**；传父菜单 ID 会静默返回空数组
 *    （方法名读起来像「查这些菜单下的按钮」，实际不是）。
 */
@Injectable()
export class MenuService {
  constructor(
    private readonly prisma: PrismaService,
    @Inject(forwardRef(() => UserService))
    private readonly userService: UserService,
    @Inject(forwardRef(() => RolePermService))
    private readonly rolePermService: RolePermService
  ) {}

  async findAll(): Promise<MenuView[]> {
    const menus = await this.prisma.sysMenu.findMany({
      orderBy: { sort: "asc" },
    });
    return menus.map(toMenuView);
  }

  async find(menuIds: (number | string)[]): Promise<MenuView[]> {
    const ids = toBigIntArray(menuIds);
    if (!ids.length) return [];

    const menus = await this.prisma.sysMenu.findMany({
      where: { id: { in: ids } },
      orderBy: { sort: "asc" },
    });
    return menus.map(toMenuView);
  }

  /**
   * 获取所有按钮权限标识
   */
  async findALLButtons(): Promise<string[]> {
    const buttons = await this.prisma.sysMenu.findMany({
      where: { menuType: "B", visible: 1 },
      select: { perm: true },
    });

    return Array.from(
      new Set(buttons.map((menu) => menu.perm?.trim()).filter((perm): perm is string => !!perm))
    );
  }

  async findButtons(menuIds: string[]) {
    const ids = toBigIntArray(menuIds);
    if (!ids.length) return [];

    const permslist = await this.prisma.sysMenu.findMany({
      where: { id: { in: ids }, menuType: "B" },
      orderBy: { sort: "asc" },
    });
    return permslist.map((item) => item.perm).filter((perm): perm is string => !!perm);
  }

  /**
   * 根据菜单ID查询权限集合
   */
  async findPermsByMenuIds(menuIds: string[]): Promise<string[]> {
    if (!menuIds?.length) return [];

    const ids = toBigIntArray(menuIds);
    if (!ids.length) return [];

    const menus = await this.prisma.sysMenu.findMany({
      where: { id: { in: ids }, menuType: "B" },
      select: { perm: true },
    });

    return Array.from(
      new Set(menus.map((menu) => menu.perm?.trim()).filter((perm): perm is string => !!perm))
    );
  }

  /**
   * 获取用户菜单
   */
  async getRoutes(userId: string): Promise<Route[]> {
    // 超级管理员返回所有菜单
    if (userId === "1") {
      // 后端路由用于前端注册，不仅决定侧边栏显示；因此这里会包含 visible=0 的隐藏菜单
      const menuList = await this.prisma.sysMenu.findMany({
        where: { menuType: { in: ["C", "M"] } },
        orderBy: { sort: "asc" },
      });
      return this.buildRoutes(menuList.map(toMenuView));
    }

    // 其他用户返回其角色对应的菜单
    const menuIds = await this.userService.getUserMenuIds(userId);
    if (!menuIds || menuIds.length === 0) {
      return [];
    }

    const ids = toBigIntArray(menuIds);
    if (!ids.length) return [];

    // 保持路由完整，防止路由未注册问题
    const menuList = await this.prisma.sysMenu.findMany({
      where: { id: { in: ids }, menuType: { in: ["C", "M"] } },
      orderBy: { sort: "asc" },
    });
    return this.buildRoutes(menuList.map(toMenuView));
  }

  /**
   * 获取菜单树形表格列表
   *
   * 语义：先按关键字捞出命中项，再把命中项的**祖先链**补进结果集，
   * 最后整片建树（`treePath` 是逗号分隔的「祖先…自身」路径，故补祖先只需拆它）。
   * 因此「只命中深层节点」时，父链会一起返回，树不会断 —— 这一点与 `dept` 模块
   * 的「孤儿丢弃」语义不同，属本模块特有行为，保持原样。
   */
  async getMenus(keyword: string) {
    let matchedMenus: SysMenuModel[];
    if (keyword) {
      // MySQL 默认排序规则不区分大小写，PG 的 LIKE 区分 ⇒ 显式 insensitive
      matchedMenus = await this.prisma.sysMenu.findMany({
        where: { name: { contains: keyword, mode: "insensitive" } },
        orderBy: { sort: "asc" },
      });
    } else {
      matchedMenus = await this.prisma.sysMenu.findMany({
        orderBy: { sort: "asc" },
      });
      return this.buildMenuTree(matchedMenus.map(toMenuView));
    }

    if (matchedMenus.length === 0) {
      return [];
    }

    const allMenuIds = new Set<string>();
    matchedMenus.forEach((menu) => {
      allMenuIds.add(menu.id.toString());
      if (menu.treePath) {
        const parentIds = menu.treePath.split(",").filter(Boolean);
        parentIds.forEach((id) => allMenuIds.add(id));
      }
    });

    const allIds = toBigIntArray(Array.from(allMenuIds));
    const allMenus = allIds.length
      ? await this.prisma.sysMenu.findMany({
          where: { id: { in: allIds } },
          orderBy: { sort: "asc" },
        })
      : [];

    return this.buildMenuTree(allMenus.map(toMenuView));
  }

  /**
   * 获取菜单下拉树形列表
   */
  async findOptions() {
    const menus = await this.prisma.sysMenu.findMany({
      select: { id: true, name: true, parentId: true },
      orderBy: { sort: "asc" },
    });
    return this.buildOptionsTree(
      menus.map((menu) => ({
        id: menu.id.toString(),
        name: menu.name,
        parentId: menu.parentId.toString(),
      }))
    );
  }

  /**
   * 创建菜单
   *
   * 保留原实现的**两段式落库**：先 INSERT（`tree_path` 只写到父路径），
   * 拿到自增主键后再 UPDATE 把自身 ID 追加进去。
   * 于是最终形态是：
   *  · 顶层：`tree_path = 自身ID`（**不含** `"0"`）
   *  · 子级：`tree_path = 父的tree_path + "," + 自身ID`
   * `getMenus()` 的祖先补全依赖这个约定（`treePath.split(",")` 里含自身也无妨）。
   */
  async create(createMenuDto: CreateMenuDto) {
    const { type, routePath } = createMenuDto;

    // 判断是否为外链菜单
    const isExternalLink =
      type === "M" &&
      !!routePath &&
      (routePath.startsWith("http://") || routePath.startsWith("https://"));

    // 目录类型处理
    let component = createMenuDto.component;
    // 一级目录需以 / 开头（原实现直接改写 DTO，这里用局部变量承接）
    let normalizedRoutePath = routePath;
    if (type === "C") {
      if (
        (!createMenuDto.parentId || createMenuDto.parentId === "0") &&
        routePath &&
        !routePath.startsWith("/")
      ) {
        normalizedRoutePath = "/" + routePath;
      }
      component = "Layout";
    } else if (isExternalLink) {
      // 外链菜单组件设为 null
      component = null;
    }

    const parentIdStr = createMenuDto.parentId || "0";
    // 缺省/`"0"` ⇒ 顶层。非空但解析不出数字时**提前失败**：
    // 原实现会把 `"abc"` 直接塞进 bigint 列，由 MySQL 报
    // `Incorrect integer value` 抛 500；这里换成语义明确的业务错误。
    const parentIdBig = toBigInt(parentIdStr);
    if (parentIdBig === null) {
      throw new BusinessException("父菜单ID格式不正确");
    }

    // 生成 treePath
    const treePath = await this.generateMenuTreePath(parentIdStr);
    const now = new Date();

    const data: Prisma.SysMenuUncheckedCreateInput = {
      name: createMenuDto.name,
      menuType: type,
      parentId: parentIdBig,
      treePath,
      component: component ?? null,
      // 原实现走 save()，由 AuditSubscriber 填 createTime / updateTime；
      // `sys_menu` 无 create_by / update_by 列，故只需补这两个时间列。
      createTime: now,
      updateTime: now,
    };
    // 只写显式传入的可选列：省略时套用列默认值（`sort` 0 / `visible` 1 / `alwaysShow` 0 / `keepAlive` 0），
    // 与原 INSERT 省略该列的行为一致。
    // ⚠️ `permissionType` / `authSymbol` / `orderWeight` / `remark` / `createTab` 不在列中 ⇒ 一律丢弃。
    if (normalizedRoutePath !== undefined) data.routePath = normalizedRoutePath;
    if (createMenuDto.routeName !== undefined) data.routeName = createMenuDto.routeName;
    if (createMenuDto.perm !== undefined) data.perm = createMenuDto.perm;
    if (createMenuDto.icon !== undefined) data.icon = createMenuDto.icon;
    if (createMenuDto.redirect !== undefined) data.redirect = createMenuDto.redirect;
    if (createMenuDto.sort !== undefined) data.sort = createMenuDto.sort;
    if (createMenuDto.alwaysShow !== undefined) data.alwaysShow = createMenuDto.alwaysShow;
    if (createMenuDto.keepAlive !== undefined) data.keepAlive = createMenuDto.keepAlive;
    if (createMenuDto.visible !== undefined) data.visible = createMenuDto.visible;
    if (createMenuDto.params !== undefined)
      data.params = createMenuDto.params as Prisma.InputJsonValue;

    const created = await this.prisma.sysMenu.create({ data });

    // 更新菜单 ID 到 treePath（对齐原实现第二次 save()；该次 save 触发订阅器刷新 updateTime）
    const finalTreePath =
      parentIdStr === "0" ? created.id.toString() : `${treePath},${created.id.toString()}`;
    await this.prisma.sysMenu.update({
      where: { id: created.id },
      data: { treePath: finalTreePath, updateTime: new Date() },
    });

    return true;
  }

  /**
   * 生成菜单树路径
   *
   * 返回**父节点自身**的 `tree_path`（不是「父 + 父ID」）：自身 ID 由调用方在拿到主键后追加。
   * 父节点不存在或 ID 非法时返回 `"0"`（即该菜单落成顶层），这是原实现的行为，保持原样。
   */
  private async generateMenuTreePath(parentId: string): Promise<string> {
    if (!parentId || parentId === "0") {
      return "0";
    }
    const pid = toBigInt(parentId);
    if (pid === null) {
      return "0";
    }
    const parent = await this.prisma.sysMenu.findFirst({
      where: { id: pid },
      select: { id: true, treePath: true },
    });
    if (!parent) {
      return "0";
    }
    return parent.treePath || "0";
  }

  /**
   * 获取菜单表单
   */
  async getMenuForm(id: string | number) {
    // 非法 ID 视为「不存在」（原实现会把字符串直接下推给引擎并抛 500）
    const menuId = toBigInt(id);
    if (menuId === null) return null;

    const menu = await this.prisma.sysMenu.findFirst({ where: { id: menuId } });
    if (!menu) return null;

    // params: {k: v} -> [{key: k, value: v}]
    const result: any = { ...toMenuView(menu) };
    const rawParams = menu.params;
    if (rawParams && typeof rawParams === "object") {
      result.params = Object.entries(rawParams as Record<string, unknown>).map(([key, value]) => ({
        key,
        value: String(value),
      }));
    } else {
      result.params = null;
    }
    return result;
  }

  /**
   * 更新菜单
   */
  async update(id: string | number, updateMenuDto: UpdateMenuDto) {
    const menuId = toBigInt(id);
    if (menuId === null) return null;

    const menu = await this.prisma.sysMenu.findFirst({ where: { id: menuId } });
    if (!menu) {
      return null;
    }

    const { type, routePath, parentId } = updateMenuDto;

    // 判断是否为外链菜单
    const isExternalLink =
      type === "M" &&
      !!routePath &&
      (routePath.startsWith("http://") || routePath.startsWith("https://"));

    // 目录类型处理
    let component = updateMenuDto.component ?? menu.component;
    let normalizedRoutePath = routePath;
    if (type === "C") {
      // 一级目录需以 / 开头
      if ((!parentId || parentId === "0") && routePath && !routePath.startsWith("/")) {
        normalizedRoutePath = "/" + routePath;
      }
      component = "Layout";
    } else if (isExternalLink) {
      component = null;
    }

    const idStr = menu.id.toString();
    // 检查父级不能为自己
    if (parentId === idStr) {
      throw new Error("父级菜单不能为当前菜单");
    }

    const currentParentIdStr = menu.parentId.toString();
    // 🔴 缺陷 1 的修复点：只有请求**显式给出** parentId 时才动 parentId / treePath。
    //    `undefined` / `null` / 空串 / 纯空白 都算「未给出」⇒ 保持原父级，不重算 treePath，
    //    也不级联改写子孙。这样 `PATCH /menus/:id?visible=0` 才不会把子树搬到根节点。
    const parentProvided =
      parentId !== undefined && parentId !== null && String(parentId).trim() !== "";
    const newParentIdStr = parentProvided ? String(parentId).trim() : currentParentIdStr;
    const newParentId = toBigInt(newParentIdStr);
    if (newParentId === null) {
      throw new BusinessException("父菜单ID格式不正确");
    }

    // 重新计算 treePath（如果父级变化）
    let newTreePath = menu.treePath;
    const parentChanged = newParentId !== menu.parentId;
    if (parentChanged) {
      newTreePath = await this.generateMenuTreePath(newParentIdStr);
    }

    const data: Prisma.SysMenuUncheckedUpdateInput = {
      // component / parentId / treePath 每次都显式写入（对齐原实现 updatedMenu 里恒有这三个键；
      // 值未变时写回原值是幂等的）
      component: component ?? null,
      parentId: newParentId,
      treePath: newTreePath,
      updateTime: new Date(),
    };
    // 只写显式传入的列 —— 这正是缺陷 2 的修复点（对齐 TypeORM `update()` 跳过 `undefined` 的语义，
    // 同时不再把表里不存在的 DTO 字段下推给引擎）。
    if (updateMenuDto.name !== undefined) data.name = updateMenuDto.name;
    if (type !== undefined) data.menuType = type;
    if (normalizedRoutePath !== undefined) data.routePath = normalizedRoutePath;
    if (updateMenuDto.routeName !== undefined) data.routeName = updateMenuDto.routeName;
    if (updateMenuDto.perm !== undefined) data.perm = updateMenuDto.perm;
    if (updateMenuDto.icon !== undefined) data.icon = updateMenuDto.icon;
    if (updateMenuDto.redirect !== undefined) data.redirect = updateMenuDto.redirect;
    if (updateMenuDto.sort !== undefined) data.sort = updateMenuDto.sort;
    if (updateMenuDto.alwaysShow !== undefined) data.alwaysShow = updateMenuDto.alwaysShow;
    if (updateMenuDto.keepAlive !== undefined) data.keepAlive = updateMenuDto.keepAlive;
    if (updateMenuDto.visible !== undefined) data.visible = updateMenuDto.visible;
    if (updateMenuDto.params !== undefined) {
      // 可空 Json 列：传 `null` 必须用 `Prisma.DbNull`（SQL NULL），
      // 直接给 `null` 会被 Prisma 拒绝（它要求区分 JSON null 与 SQL NULL）
      data.params =
        updateMenuDto.params === null
          ? Prisma.DbNull
          : (updateMenuDto.params as Prisma.InputJsonValue);
    }

    await this.prisma.sysMenu.update({ where: { id: menuId }, data });

    // 更新子菜单的 treePath
    if (parentChanged) {
      await this.updateChildrenTreePath(idStr, newTreePath ?? "0");
    }

    // 刷新角色权限缓存
    await this.rolePermService.refreshAllRolePermsCache();

    return true;
  }

  /**
   * 更新子菜单树路径
   */
  private async updateChildrenTreePath(id: string, treePath: string): Promise<void> {
    const idBig = toBigInt(id);
    if (idBig === null) return;

    const children = await this.prisma.sysMenu.findMany({
      where: { parentId: idBig },
    });

    if (children.length > 0) {
      const childTreePath = `${treePath},${id}`;
      for (const child of children) {
        // 原实现走 `repository.update()`，**不触发** AuditSubscriber ⇒ 这里同样不刷新 updateTime
        await this.prisma.sysMenu.update({
          where: { id: child.id },
          data: { treePath: childTreePath },
        });
        await this.updateChildrenTreePath(child.id.toString(), childTreePath);
      }
    }
  }

  /**
   * 删除菜单（级联删除子菜单）
   *
   * 物理删除（`sys_menu` 无 `is_deleted`）。
   * 非法 ID 不再抛 500（原实现把字符串下推给引擎会报错），而是按「无可删」处理并返回 `true`,
   * 与原实现对「不存在的合法 ID」静默成功的语义一致。
   */
  async deleteMenu(id: string | number) {
    const idStr = id.toString();

    // 查找所有子菜单（包括嵌套的）
    const allMenus = await this.prisma.sysMenu.findMany({
      select: { id: true, parentId: true },
    });

    const idsToDelete = new Set<string>([idStr]);

    // 递归查找子菜单
    const findChildren = (parentId: string) => {
      for (const menu of allMenus) {
        if (menu.parentId.toString() === parentId) {
          const childId = menu.id.toString();
          // 原实现无环保护：若数据里出现「自己的父级是自己」会无限递归。
          // 这里用 Set 判重收口，正常树形下行为不变。
          if (idsToDelete.has(childId)) continue;
          idsToDelete.add(childId);
          findChildren(childId);
        }
      }
    };
    findChildren(idStr);

    const idList = toBigIntArray(Array.from(idsToDelete));
    if (idList.length > 0) {
      await this.prisma.sysMenu.deleteMany({ where: { id: { in: idList } } });
    }

    // 刷新角色权限缓存
    await this.rolePermService.refreshAllRolePermsCache();

    return true;
  }

  /**
   * 菜单树形数据处理
   */
  private buildMenuTree(menuList: MenuView[]): any[] {
    const map: { [key: string]: any } = {};
    const roots: any[] = [];

    menuList.forEach((menu) => {
      map[menu.id] = {
        ...menu,
        children: [],
      };
    });

    menuList.forEach((menu) => {
      if (isRootMenu(menu)) {
        roots.push(map[menu.id]);
      } else {
        if (map[menu.parentId]) {
          map[menu.parentId].children.push(map[menu.id]);
        }
      }
    });

    return roots;
  }

  /**
   * 构建菜单选项树
   */
  private buildOptionsTree(menus: { id: string; name: string; parentId: string }[]): any[] {
    const map: { [key: string]: any } = {};
    const roots: any[] = [];

    menus.forEach((menu) => {
      map[menu.id] = {
        value: menu.id,
        label: menu.name,
        children: [],
      };
    });

    menus.forEach((menu) => {
      if (isRootMenu(menu)) {
        roots.push(map[menu.id]);
      } else {
        if (map[menu.parentId]) {
          map[menu.parentId].children.push(map[menu.id]);
        }
      }
    });

    return roots;
  }

  /**
   * 构建前端路由
   */
  private buildRoutes(menus: MenuView[], parentId: string = "0"): Route[] {
    const routes: Route[] = [];

    menus.forEach((menu) => {
      if (menu.parentId === parentId) {
        const route: Route = {
          path: menu.routePath || "",
          component: menu.component || "",
          name: menu.routeName || "",
          meta: {
            title: menu.name,
            icon: menu.icon || "",
            hidden: menu.visible === 0,
            keepAlive: menu.keepAlive === 1,
            alwaysShow: menu.alwaysShow === 1,
            params: this.parseMenuParams(menu.params),
          },
          children: this.buildRoutes(menus, menu.id),
        };

        if (route.children.length === 0) {
          delete route.children;
        }

        routes.push(route);
      }
    });

    return routes;
  }

  private parseMenuParams(raw: unknown): Record<string, any> {
    if (!raw) return {};

    if (typeof raw === "object") {
      return raw as Record<string, any>;
    }

    if (typeof raw === "string") {
      try {
        const parsed = JSON.parse(raw);
        return typeof parsed === "object" && parsed !== null ? parsed : {};
      } catch {
        return {};
      }
    }

    return {};
  }

  /**
   * 代码生成菜单
   *
   * 原实现按 `parentMenuId` 建一个 `M` 菜单，再挂 6 个动作按钮。
   * 【已知偏差·保持原行为】`treePath` 用的是 `${父.treePath},${父ID}` ——
   * 父的 `treePath` 本就以父自身结尾，于是这里会把父 ID **重复一次**（如 `"5,5"`）；
   * 且父 `treePath` 为 NULL 时会拼出字面量 `"null,5"`。两处都照搬，不做改动。
   */
  async addMenuForCodegen(
    parentMenuId: number,
    tableName: string,
    moduleName: string,
    businessName: string,
    entityName: string
  ): Promise<void> {
    const parentIdBig = toBigInt(parentMenuId);
    if (parentIdBig === null) {
      return;
    }

    const parent = await this.prisma.sysMenu.findFirst({ where: { id: parentIdBig } });
    if (!parent) {
      return;
    }

    // 计算同级最大排序号 +1
    let sort = 1;
    const maxSortMenu = await this.prisma.sysMenu.findFirst({
      where: { parentId: parentIdBig },
      orderBy: { sort: "desc" },
    });
    if (maxSortMenu) {
      sort = maxSortMenu.sort + 1;
    }

    // 构建菜单实体
    const parentIdStr = parentIdBig.toString();
    const entityKebab = this.toKebabCase(entityName);
    const treePath = `${parent.treePath},${parentIdStr}`;

    // 创建菜单记录
    const menu = await this.prisma.sysMenu.create({
      data: {
        parentId: parentIdBig,
        menuType: "M",
        name: businessName,
        routeName: entityName,
        routePath: entityKebab,
        component: `${moduleName}/${entityKebab}/index`,
        sort,
        visible: 1,
        treePath,
        createTime: new Date(),
        updateTime: new Date(),
      },
    });

    // 生成按钮权限标识
    const permPrefix = `${moduleName}:${tableName.replace(/_/g, "-")}:`;
    const actions = ["add", "edit", "delete", "detail", "export", "import"];
    for (let i = 0; i < actions.length; i++) {
      const action = actions[i];
      await this.prisma.sysMenu.create({
        data: {
          parentId: menu.id,
          menuType: "B",
          name: action,
          perm: permPrefix + action,
          sort: i + 1,
          treePath: `${treePath},${menu.id.toString()}`,
          createTime: new Date(),
          updateTime: new Date(),
        },
      });
    }
  }

  /**
   * 驼峰转换为kebab-case
   */
  private toKebabCase(s: string): string {
    if (!s) return "";
    let result = "";
    for (let i = 0; i < s.length; i++) {
      const c = s[i];
      if (i > 0 && c >= "A" && c <= "Z") {
        result += "-";
      }
      result += c.toLowerCase();
    }
    return result;
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Put,
  Query,
  Req,
  SetMetadata,
} from "@nestjs/common";
import { ApiOperation, ApiTags } from "@nestjs/swagger";
import { Permissions } from "../../common/decorators/auth.decorator";
import { Log } from "../../common/decorators/log.decorator";
import { ActionTypeValue } from "../../common/enums/action-type.enum";
